var BANK=[
/* ================ YEAR 11 · PROGRAMMING FUNDAMENTALS ================ */
 {id:'pf1',yr:11,mod:'pf',dots:['pf-01'],type:'mcq',xp:30,
  prompt:'Which option lists the fundamental software development steps in the correct order?',
  options:['Requirements definition → design → determining specifications → development → testing and debugging → integration → installation → maintenance','Determining specifications → requirements definition → design → development → integration → testing and debugging → installation → maintenance','Requirements definition → determining specifications → design → development → integration → testing and debugging → installation → maintenance','Requirements definition → determining specifications → design → development → testing and debugging → integration → installation → maintenance','Requirements definition → determining specifications → design → development → integration → installation → testing and debugging → maintenance'],answer:2,
  explain:'The full sequence is requirements definition → determining specifications → design → development → integration → testing and debugging → installation → maintenance. Distractor D swaps integration with testing and debugging — modules are integrated FIRST, then the combined system is tested and debugged. E installs before testing; A promotes design ahead of the specifications it must follow; B reverses the first two steps.'},
 {id:'pf2',yr:11,mod:'pf',dots:['pf-01'],type:'mcq',xp:30,
  prompt:'A team has just finished the development step of the fundamental sequence. Which two steps come next, in the correct order?',
  options:['Testing and debugging, then installation','Integration, then testing and debugging','Integration, then installation','Installation, then maintenance','Testing and debugging, then integration'],answer:1,
  explain:'After development the modules are INTEGRATED — joined into one system — and only then is the combined system tested and debugged. Installation and maintenance follow later, and maintenance is the longest-lived stage of the eight.'},
 {id:'pf3',yr:11,mod:'pf',dots:['pf-02'],type:'mcq',xp:30,
  prompt:'A post-test REPEAT…UNTIL loop is rewritten in Python with while True and a break. The UNTIL condition is x >= 100 — the loop stops when it becomes true. If the value read on the very first pass is 150, how many times does the loop body execute?',
  options:['0 — the condition is already true, so the body is skipped','1 — a post-test body always runs once, prior to the check','2 — once to read, once to confirm','It cannot be determined without the other inputs','Infinite — 150 always satisfies the condition'],answer:1,
  explain:'Post-test iteration checks the condition AFTER the body, so the body is guaranteed at least one execution — even input that already satisfies the exit condition runs the body once. A pre-test while loop with the same condition would execute zero times. Choosing between pre- and post-test is precisely a decision about this boundary.'},
 {id:'pf4',yr:11,mod:'pf',dots:['pf-02'],type:'output',xp:50,lang:'py',
  prompt:'What does this Python fragment print?',
  code:'total = 0\nfor i in range(1, 5):\n    if i % 2 == 0:\n        total = total + i * i\n    else:\n        total = total + i\nprint(total)',
  options:['17','20','30','24'],answer:3,
  explain:'Trace the table: i = 1 is odd → add 1; i = 2 is even → add 4; i = 3 odd → add 3; i = 4 even → add 16. Total 1 + 4 + 3 + 16 = 24. The modulo test i % 2 == 0 selects the evens, range(1, 5) stops BEFORE 5, and the squaring applies only to the even branch.'},
 {id:'pf5',yr:11,mod:'pf',dots:['pf-03'],type:'mcq',xp:30,
  prompt:'A Sudoku solver assigns a digit, checks the constraints, undoes the assignment the moment a conflict appears, and returns to the previous square. A merge sort splits a list into halves, sorts each half independently, and merges the results. Which pairing of design strategy to mechanism is correct?',
  options:['Sudoku = divide and conquer because the board divides into rows; merge sort = backtracking, revisiting earlier halves','Both are divide and conquer — every recursive algorithm divides the data, so the two are identical','Both are backtracking — both undo moves when a conflict appears and retreat to the last choice','Sudoku = brute force with no underlying strategy; merge sort = backtracking, since merging undoes the split','Sudoku = backtracking — abandon placements that cannot succeed; merge sort = divide and conquer — combine halves'],answer:4,
  explain:'Backtracking abandons partial solutions that cannot succeed and returns to the last decision point — exactly the Sudoku solver. Divide and conquer splits the data into INDEPENDENT subproblems, solves each, and combines — exactly merge sort. Recursion alone does not make an algorithm divide and conquer, and the Sudoku solver does have a strategy.'},
 {id:'pf6',yr:11,mod:'pf',dots:['pf-03'],type:'mcq',xp:30,
  prompt:'A binary search runs on a sorted list of exactly 500 items. The MAXIMUM number of comparisons needed to find any item — or prove it is absent — is:',
  options:['8','10','250','500','9'],answer:4,
  explain:'Each comparison halves what remains. 2 to the power 8 = 256 covers fewer than the 501 possible outcomes, while 2 to the power 9 = 512 covers them all — so nine comparisons always suffice and eight cannot. 250 and 500 are linear-scan figures, not divide-and-conquer figures.'},
 {id:'pf7',yr:11,mod:'pf',dots:['pf-04'],type:'mcq',xp:30,
  prompt:'A flowchart for a mark-processing algorithm must be drawn with standard symbols. Which pairing of symbol to meaning is correct?',
  options:['Diamond = process step; rectangle = decision with two labelled exits','Parallelogram = decision with two exits; diamond = input or output','Diamond = decision with true/false exits; parallelogram = input or output','Oval = process; diamond = connector between pages of a chart','Rectangle = decision with three exits; diamond = a single-flow process step'],answer:2,
  explain:'Diamonds are decisions — one entry, two labelled exits (true/false). Parallelograms are input and output. Rectangles are ordinary processes and ovals are terminators (start/stop). Choosing symbols by their precise meaning is what makes a flowchart readable by anyone else.'},
 {id:'pf8',yr:11,mod:'pf',dots:['pf-04'],type:'mcq',xp:30,
  prompt:'A subprogram is written to compute one result and hand it back to the caller, changing nothing else. Precisely, this subprogram is:',
  options:['A procedure — procedures return values through their parameters','A function — it performs a task AND returns a value','A stub — it stands in for logic not yet written','A global variable — it carries the result between calls','A parameter — it passes data into the caller'],answer:1,
  explain:'A procedure performs a task but returns no value; a function performs a task AND returns exactly that value. The distinction matters in design: a call to a function becomes an expression in the caller, a call to a procedure becomes a statement.'},
 {id:'pf9',yr:11,mod:'pf',dots:['pf-05'],type:'mcq',xp:30,
  prompt:'A designer starts from the whole system, repeatedly divides it into smaller modules, and draws each level of calling detail as it is decided. The diagram and the design direction are:',
  options:['A structure chart, rendered top-down','A refinement diagram, drawn bottom-up','A data flow diagram, drawn top-down','A structure chart, drawn bottom-up','A refinement diagram, drawn top-down'],answer:0,
  explain:'Structure charts decompose a system into modules and show which module calls which — the natural companion of top-down design. Refinement diagrams track how each abstraction is progressively filled in with implementable detail (they do not show call hierarchy), and data flow diagrams trace data movement, not calls.'},
 {id:'pf10',yr:11,mod:'pf',dots:['pf-10'],type:'output',xp:50,lang:'py',
  prompt:'What does this Python fragment print, in order?',
  code:'a = "7"\nb = 3\nprint(int(a) * b)\nprint(a * b)',
  options:['21 then 777','777 then 21','21 then 21','A TypeError on line 4','7 then 777'],answer:0,
  explain:'int("7") explicitly converts, so 7 × 3 = 21. But "7" * 3 is string REPETITION — the string is repeated three times: 777. Python never silently coerces text to numbers; the data type of the operands decides what the operator means.'},
 {id:'pf11',yr:11,mod:'pf',dots:['pf-06'],type:'output',xp:50,lang:'py',
  prompt:'Desk-check this algorithm — what line does it print?',
  code:'x = 27\ncount = 0\nwhile x > 1:\n    x = x // 2\ncount = count + 1\nprint(x, count)',
  options:['1 4','0 4','1 1','1 3','4 1'],answer:2,
  explain:'The while trace: 27 → 13 → 6 → 3 → 1 — four passes, stopping because 1 > 1 is false. But read the indentation precisely: the update to count is NOT indented under the while, so it is not part of the loop body — it runs exactly once after the loop ends. count is therefore 1, not 4: the program prints 1 1. Assuming "count = count + 1 belongs to the loop" without checking indentation is precisely the fault this desk check exposes.'},
 {id:'pf12',yr:11,mod:'pf',dots:['pf-12','pf-10'],type:'fix',xp:100,lang:'py',
  prompt:'The grade classifier fails acceptance tests. Spec: 85 or more is "A"; 70 to 84 is "B"; 65 to 69 is "C"; below 65 is "F". Patch it so every test passes.',
  starter:'# GRADE CLASSIFIER :: acceptance test failure\n# Spec: 85 or more = "A"; 70-84 = "B";\n# 65-69 = "C"; below 65 = "F"\ndef grade(mark):\n    if mark >= 85:\n        return "A"\n    if mark > 70:\n        return "B"\n    if mark >= 65:\n        return "C"\n    return "F"',
  tests:[{label:'grade(85) → "A"',expr:'grade(85)',expect:'A'},
   {label:'grade(84) → "B"',expr:'grade(84)',expect:'B'},
   {label:'grade(70) → "B"',expr:'grade(70)',expect:'B'},
   {label:'grade(69) → "C"',expr:'grade(69)',expect:'C'},
   {label:'grade(65) → "C"',expr:'grade(65)',expect:'C'},
   {label:'grade(64) → "F"',expr:'grade(64)',expect:'F'}],
  explain:'The spec puts 70 inside band B, so the test must be mark >= 70. With mark > 70, exactly-70 falls through to C — the classic off-by-one boundary fault that boundary-value test data (65, 69, 70) exists to expose. Each threshold belongs to the band whose condition it satisfies.'},
 {id:'pf13',yr:11,mod:'pf',dots:['pf-06'],type:'mcq',xp:30,
  prompt:'Which pairing of checking techniques is correct?',
  options:['Desk checking — hand-tracing variables with chosen test data; peer checking — a second person reads the code','Desk checking — the IDE runs the tests; peer checking — the compiler reports every warning','Desk checking — the client reviews the requirements; peer checking — the team reviews the plan','Desk checking and peer checking are just two different names for the very same review activity','Peer checking — running the program twice and comparing outputs; desk checking — comparing with a colleague’s run'],answer:0,
  explain:'Desk checking is manual execution: act as the computer and record each variable’s value after each step, using planned test data. Peer checking adds a second pair of eyes on the code itself — the reviewer catches what familiarity hides. Neither technique requires running the program at all.'},
 {id:'pf14',yr:11,mod:'pf',dots:['pf-09','pf-10'],type:'output',xp:50,lang:'py',
  prompt:'What does this Python fragment print, in order?',
  code:'digits = [4, 8, 15, 16, 23, 42]\nprint(digits[1:4])\nprint(digits[-2:])\nprint(len(digits[2:5]))',
  options:['[8, 15, 16] then [23, 42] then 3','[8, 15, 16] then [16, 23] then 3','[8, 15, 16] then [23, 42] then 4','[4, 8, 15] then [23, 42] then 3','[8, 15, 16, 23] then [23, 42] then 3'],answer:0,
  explain:'A slice takes from the start index UP TO BUT NOT INCLUDING the stop index: digits[1:4] is positions 1, 2, 3 → [8, 15, 16]. Negative indices count from the end: -2 is 23, and the slice runs to the end → [23, 42]. digits[2:5] covers three positions, so len is 3 — the stop index 5 is itself excluded.'},
 {id:'pf15',yr:11,mod:'pf',dots:['pf-07'],type:'output',xp:50,lang:'py',
  prompt:'What does this Python fragment print, in order?',
  code:'code = ord("C")\nprint(code)\nprint(chr(code + 2))\nprint(ord("a") - ord("A"))',
  options:['67 then E then 30','68 then F then 32','67 then E then 32','67 then D then 26','67 then E then 26'],answer:2,
  explain:'In ASCII, "A" is 65 and "C" is 67 (A = 65, B = 66, C = 67). chr(67 + 2) = chr(69) = "E". Lowercase letters sit 32 above their uppercase forms: ord("a") is 97, so 97 − 65 = 32. Character codes are just integers — which is why chr/ord arithmetic underlies so many encoding tricks.'},
 {id:'pf16',yr:11,mod:'pf',dots:['pf-07'],type:'mcq',xp:30,
  prompt:'The 8-bit pattern 10111110 written as two hexadecimal digits is:',
  options:['10BE','BD','7E','EB','BE'],answer:4,
  explain:'One hex digit encodes exactly four bits: 1011 in binary is 11 in decimal, written B; 1110 is 14, written E — giving BE. BD mis-decodes the second nibble, EB reverses the nibble order, 7E mis-decodes the first, and 10BE treats the pattern as decimal digits. Split any binary number into 4-bit nibbles from the right to convert.'},
 {id:'pf17',yr:11,mod:'pf',dots:['pf-07'],type:'mcq',xp:30,
  prompt:'For 8-bit two’s complement, the representable range and the stored pattern for −1 are:',
  options:['−127 to +127; −1 is stored as 10000001','−128 to +127; −1 is stored as 11111111','−128 to +128; −1 is stored as 11111110','−255 to +255; −1 is stored as 11111110','−128 to +127; −1 is stored as 10000000'],answer:1,
  explain:'n bits hold −2^(n−1) to +2^(n−1) − 1, so 8 bits give −128 to +127 — the extra negative value exists because there is no −0. −1 is the pattern with every bit set: 11111111. Invert it and you get 00000000; add one and it is still 00000000 — the defining check for −1.'},
 {id:'pf18',yr:11,mod:'pf',dots:['pf-08'],type:'output',xp:50,lang:'py',
  prompt:'What does this Python fragment print, in order?',
  code:'a = 7 // 2\nb = 7 / 2\nprint(a, b)\nprint(round(b, 1))\nprint(2 ** 3 % 5)',
  options:['3.5 3.5 then 4 then 3','3 3.5 then 4 then 2.4','4 3.5 then 3.5 then 1.6','3 3.5 then 3.5 then 3','3 3.75 then 3.8 then 3'],answer:3,
  explain:'// is integer (floor) division → 3; / is real division → 3.5, which prints as 3.5. round(3.5, 1) leaves 3.5 unchanged. Exponentiation binds before modulo, so 2 ** 3 % 5 means (2 ** 3) % 5 = 8 % 5 = 3. Operator precedence and the // versus / distinction are both under test here.'},
 {id:'pf19',yr:11,mod:'pf',dots:['pf-08'],type:'mcq',xp:30,
  prompt:'A data dictionary entry is being written for the field price, which holds values like 19.99. Which entry is correct?',
  options:['name: price; type: integer; description: price in whole dollars, cents dropped','name: price; type: string; description: display text, keeps the $ sign','name: price; type: real; description: sale price in dollars; relates to orders','name: PRICE_FIELD; type: Boolean; description: an on/off flag for all pricing','record current values 19.99, 24.50 and 7.00 so the dictionary shows live data'],answer:2,
  explain:'A data dictionary is a design-time record: for each item it lists the name, the data type (integer, real, string, Boolean, date…), a description of meaning and constraints, and the relationships to other data. A price with cents is a real — an integer would destroy the cents and text could not be totalled. Runtime values never belong in the dictionary.'},
 {id:'pf20',yr:11,mod:'pf',dots:['pf-10'],type:'output',xp:50,lang:'py',
  prompt:'What does this subprogram print?',
  code:'def mystery(word):\n    out = ""\n    for ch in word:\n        out = ch + out\n    return out\n\nprint(mystery("PRISM"))',
  options:['PRISM','MSIRP','MIRSP','MSPRI','RSIMP'],answer:1,
  explain:'Each character is PREPENDED to the accumulator: P, then RP, then SRP, then ISRP, then MSIRP — the routine reverses its input. The parameter carries data in; the return value carries the single result out.'},
 {id:'pf21',yr:11,mod:'pf',dots:['pf-12','pf-10'],type:'fix',xp:100,lang:'py',
  prompt:'second_largest must return the second largest DISTINCT value in a list, or None when fewer than two distinct values exist. It passes the happy-path test but fails every acceptance test. Patch it.',
  starter:'# SECOND LARGEST :: returns the second largest\n# DISTINCT value, or None if fewer than two\n# distinct values exist. Currently fails tests.\ndef second_largest(nums):\n    best = 0\n    for n in nums:\n        if n > best:\n            best = n\n    return best',
  tests:[{label:'second_largest([4, 9, 1, 7]) → 7',expr:'second_largest([4, 9, 1, 7])',expect:7},
   {label:'second_largest([-5, -2, -9]) → -5',expr:'second_largest([-5, -2, -9])',expect:-5},
   {label:'second_largest([5, 5, 3]) → 3',expr:'second_largest([5, 5, 3])',expect:3},
   {label:'second_largest([10]) → None',expr:'second_largest([10])',expect:null},
   {label:'second_largest([2, 2]) → None',expr:'second_largest([2, 2])',expect:null},
   {label:'second_largest([3, 9, 2, 9]) → 3',expr:'second_largest([3, 9, 2, 9])',expect:3}],
  explain:'Two faults: initialising best to 0 breaks on all-negative data (no element ever beats it), and the routine returns the LARGEST value — it never tracks the runner-up, nor handles duplicates or the too-few-distinct case. De-duplicate the values, require at least two, sort, and return the second-last — or track the top two while scanning. Exactly the class of bug that faulty and abnormal test data exposes.'},
 {id:'pf22',yr:11,mod:'pf',dots:['pf-09'],type:'mcq',xp:30,
  prompt:'Starting with an EMPTY stack, the operations are: PUSH 4, PUSH 9, POP, PUSH 2, PUSH 7, POP, POP. What was popped, in order, and what remains on the stack?',
  options:['Popped 4, 9, 7 — the stack holds 2','Popped 7, 2, 9 — the stack holds 4','Popped 9, 2, 7 — the stack is empty','Popped 9, 7, 2 — the stack holds 4','Popped 2, 7, 9 — the stack holds 4'],answer:3,
  explain:'A stack is LIFO — the last value pushed is the first popped. POP returns 9, then 7, then 2, leaving [4]. Options that pop in push order describe a QUEUE; option B pops newest-first but in the wrong sequence. The same LIFO logic drives the call stack that every recursive subprogram runs on.'},
 {id:'pf23',yr:11,mod:'pf',dots:['pf-08'],type:'output',xp:50,lang:'py',
  prompt:'A student accumulates a total and compares it against a literal. What is printed?',
  code:'total = 0.1 + 0.1 + 0.1\nprint(total == 0.3)\nprint(round(total, 1) == 0.3)',
  options:['True then False','False then True','False then False','True then True','False then None'],answer:1,
  explain:'Floating point cannot store 0.1 exactly, so three additions land a hair away from 0.3 and the exact == comparison fails. Rounding to one decimal absorbs the representation error, so the rounded comparison succeeds. Never test real values for exact equality — compare within a tolerance or round deliberately.'},
 {id:'pf24',yr:11,mod:'pf',dots:['pf-11'],type:'mcq',xp:30,
  prompt:'Which pairing of project model to defining trait is correct?',
  options:['Agile — requirements are frozen at contract sign-off','Waterfall — requirement changes mid-build are absorbed cheaply','Agile — heavy up-front documentation gates every stage','Waterfall — each stage completes once with signed-off documents','Waterfall — no documentation is produced until the project ends'],answer:3,
  explain:'Waterfall completes each stage ONCE, in sequence, with thorough signed-off documentation — its strength on stable projects and its weakness under change. Agile assumes requirements evolve and plans in short iterations instead. The traits are mutually exclusive by design, which is what makes the pairing precise.'},
 {id:'pf25',yr:11,mod:'pf',dots:['pf-11'],type:'mcq',xp:30,
  prompt:'A startup is building an app for an emerging market where requirements are expected to change weekly. Which model, and precisely why?',
  options:['Agile — short iterations treat changing requirements as routine','Waterfall — fixed stages lock the changing scope down','WAgile — the contract demands signed-off documents at every stage','Waterfall — change is cheapest late in a Waterfall project','Agile — it removes the need for any planning or documentation'],answer:0,
  explain:'Agile’s iteration cycle re-plans every sprint, so requirement change is routine input, not disruption. Waterfall penalises exactly this environment — each finished stage must be revisited — and WAgile’s up-front planning only pays when the core requirements are stable.'},
 {id:'pf26',yr:11,mod:'pf',dots:['pf-12'],type:'mcq',xp:30,
  prompt:'A validator accepts whole numbers from 1 to 99 inclusive and must reject everything else. Which test set exercises boundary data AND abnormal data?',
  options:['1 and 99 — just the two accepted limits, nothing more','0, 1, 99 and 100 — all four boundary values, never anything abnormal','0, 1, 99, 100, 2.5 and the empty string — boundary and abnormal','50 only — a single safe midpoint value and nothing else','1, 2, 98 and 99 — all accepted values, nothing beyond'],answer:2,
  explain:'Boundary data sits at and just outside each limit: 0, 1, 99, 100. Abnormal and faulty data breaks the type contract: 2.5 is not a whole number and the empty string is not a value at all. A set without the decimal and the empty string can only prove the validator rejects wrong RANGES — never wrong TYPES.'},
 {id:'pf27',yr:11,mod:'pf',dots:['pf-10'],type:'fix',xp:100,lang:'py',
  prompt:'clamp(value, lo, hi) must pin value to the range lo–hi inclusive: the value itself when it is inside the range, otherwise the NEAREST boundary. The current version returns the value unchanged. Patch it so every test passes.',
  starter:'# CLAMP :: pin value to the range lo-hi inclusive\n# Spec: return value when lo <= value <= hi,\n# otherwise return the NEAREST boundary.\n# BUG: currently returns the value unchanged.\ndef clamp(value, lo, hi):\n    return value',
  tests:[{label:'clamp(5, 0, 10) → 5',expr:'clamp(5, 0, 10)',expect:5},
   {label:'clamp(-3, 0, 10) → 0',expr:'clamp(-3, 0, 10)',expect:0},
   {label:'clamp(42, 0, 10) → 10',expr:'clamp(42, 0, 10)',expect:10},
   {label:'clamp(0, 0, 10) → 0',expr:'clamp(0, 0, 10)',expect:0},
   {label:'clamp(10, 0, 10) → 10',expr:'clamp(10, 0, 10)',expect:10},
   {label:'clamp(7, 7, 7) → 7',expr:'clamp(7, 7, 7)',expect:7}],
  explain:'Two boundary guards do it: return lo when value < lo, return hi when value > hi, and otherwise return the value untouched. The inclusive endpoints 0 and 10 must pass through unchanged — using < and > (not <= and >=) in the guards is what keeps the boundaries inside the range. Comparison direction is the whole question: returning the value when it is OUTSIDE the range would invert the spec.'},
 {id:'pf28',yr:11,mod:'pf',dots:['pf-13'],type:'mcq',xp:30,
  prompt:'A program crashes with: ValueError: invalid literal for int() with base 10: "12x" — raised while converting user input. The program otherwise follows every rule of the language. Classify the fault precisely:',
  options:['A syntax error — the int() call is misspelled or malformed','A runtime error — valid syntax, but it fails while executing','A logic error — the program finishes but the answer is silently wrong','An integration error — two modules disagree over the input format','A test-data fault, not a program fault — the code is blameless'],answer:1,
  explain:'The interpreter parsed and RAN the line — the language rules are satisfied, so this is not syntax. It halted with an error at execution time, which is the definition of a runtime error. A logic error would finish and silently produce a wrong answer; here execution stops. The cure is validating before converting — or handling the failure — not fixing spelling.'},
 {id:'pf29',yr:11,mod:'pf',dots:['pf-05'],type:'mcq',xp:30,
  prompt:'A team assembles its design from already-built, already-tested utility modules, wrapping them into larger components until the whole system exists. This design direction, and its main risk, are:',
  options:['Top-down design; the risk is missing the user’s real need','Refinement; the risk is an infinite regress of detail','Backtracking; the risk is exponential search time on failed branches','Bottom-up design; the risk is reliable parts never quite fitting','Waterfall sequencing; the risk is documentation debt piling up'],answer:3,
  explain:'Bottom-up design composes known, reliable parts first — utility modules become components, components become subsystems. Its classic risk is the integration surprise: parts that each work, but whose combination misses the top-level requirement. Top-down carries the mirror-image risk of designing abstractions whose details never materialise.'},
 {id:'pf30',yr:11,mod:'pf',dots:['pf-13'],type:'mcq',xp:30,
  prompt:'Which pairing of debugging tool to its precise use is correct?',
  options:['A watch — reports a suspect variable’s value as you step','A trace table — produced automatically by the IDE at runtime','Peer checking — running the program with reduced data','Syntax highlighting — proves the program’s logic is correct','A breakpoint — permanently deletes the line it marks'],answer:0,
  explain:'A watch shows a variable’s value as it changes while you step — the most direct evidence for "which statement changes this?". Trace tables are produced BY HAND during desk checks; peer checking is reading, not reduced runs; highlighting is cosmetic; breakpoints pause execution, they never delete code.'},
/* ---- Year 11 · Object-Oriented Paradigm ---- */
 {id:'oo1',yr:11,mod:'oo',dots:['oo-01'],type:'mcq',xp:30,
  prompt:'A class declares its fields as private and exposes only two public methods that guard them; callers never need to know the internal layout. Which pairing of OOP features is at work?',
  options:['Inheritance and generalisation — the private fields simply pass down a hierarchy of subclasses','Polymorphism and message passing — one call resolves to many different forms','Encapsulation and abstraction — state bundled with its methods, only essentials exposed','Overloading and overriding — two methods share one name in different ways','Encapsulation only — abstraction is a database term, not an OOP one'],answer:2,
  explain:'Encapsulation bundles the state with the methods that guard it; abstraction exposes only what callers need and hides the rest. No hierarchy is involved (inheritance/generalisation), no single message taking many forms (polymorphism), and the two features are distinct — hiding the layout is abstraction, bundling state with behaviour is encapsulation.'},
 {id:'oo2',yr:11,mod:'oo',dots:['oo-01'],type:'mcq',xp:30,
  prompt:'class AdminUser(User) adds a permissions attribute and reuses User’s login() unchanged. Which statement is precisely correct?',
  options:['User is the generalisation; AdminUser specialises it; login() is inherited, not overridden','AdminUser is the generalisation; User inherits from it; login() is overridden','User is the generalisation; login() is overridden simply because AdminUser explicitly calls it','This is encapsulation — login() is hidden inside the parent class entirely','This is polymorphism — login() takes many different forms across the subclasses'],answer:0,
  explain:'Generalisation extracts common features upward: User is the general class from which AdminUser specialises. Because login() is not redefined in AdminUser, it is inherited — the subclass extends rather than replaces it. Overriding would require AdminUser to supply its own login(); polymorphism would require the same message to resolve differently per object.'},
 {id:'oo3',yr:11,mod:'oo',dots:['oo-01'],type:'output',xp:50,lang:'py',
  prompt:'What is printed?',
  code:'class Accumulator:\n    def __init__(self, start):\n        self.total = start\n\n    def add(self, n):\n        self.total = self.total + n\n        return self.total\n\na = Accumulator(10)\nb = Accumulator(0)\na.add(5)\nprint(a.add(2), b.add(7))',
  options:['17 7','17 0','15 7','17 17','12 7'],answer:0,
  explain:'Each instance owns its own state: a starts at 10, add(5) → 15, add(2) → 17. b was constructed separately from 0 and its add(7) returns 7. Objects carry state between messages; the class is only the blueprint, and the value a.add(5) returned was discarded — only the second call’s return is printed.'},
 {id:'oo4',yr:11,mod:'oo',dots:['oo-01','oo-05'],type:'output',xp:50,lang:'py',
  prompt:'What is printed?',
  code:'class Employee:\n    def __init__(self, name):\n        self.name = name\n\n    def role(self):\n        return "staff"\n\nclass Manager(Employee):\n    def role(self):\n        return "boss"\n\nteam = [Employee("Dana"), Manager("Lee")]\nout = []\nfor e in team:\n    out.append(e.role())\nprint(out)',
  options:["['staff', 'boss']","['staff', 'staff']","['boss', 'boss']","['boss', 'staff']","['Dana', 'Lee']"],answer:0,
  explain:'Manager OVERRIDES role(), so a Manager object’s message resolves to the subclass version while an Employee’s resolves to the superclass version — one message, two implementations, chosen by the receiving object’s class. That is polymorphism via message passing, and it is why the loop needs no type checks.'},
 {id:'oo5',yr:11,mod:'oo',dots:['oo-02'],type:'mcq',xp:30,
  prompt:'The defining shift when refactoring function-and-global-data code into classes is:',
  options:['Global data becomes faster for every function in the program to access','Functions become longer and more detailed with every class that is added','State and its operations become owned by objects, localising changes to one class','The program stops using subprograms entirely, relying only on messages passed between objects','Testing becomes unnecessary because the objects are fully self-contained and already verified'],answer:2,
  explain:'Procedural code organises around functions acting on shared, often global, data; OOP organises around objects that own their state and the operations on it. The payoff is localisation: a state change can only happen through the owning class’s methods, so faults surface in one place instead of anywhere globals are touched.'},
 {id:'oo6',yr:11,mod:'oo',dots:['oo-03'],type:'mcq',xp:30,
  prompt:'Which assignment of model to purpose is entirely correct?',
  options:['Structure chart — data movement; data flow diagram — call hierarchy; class diagram — schedule','Class diagram — data movement; structure chart — static design; data flow diagram — call hierarchy','Data flow diagram — data movement; structure chart — call hierarchy; class diagram — static design','All three models show the same module call hierarchy, merely drawn at different levels of detail','Data flow diagram — runtime values; structure chart — data types; class diagram — SQL tables'],answer:2,
  explain:'Each model answers a different question: the DFD shows where data MOVES, the structure chart shows WHO CALLS WHOM, the class diagram shows the static design of classes, attributes and operations. Picking the model that answers the question asked is the examinable skill.'},
 {id:'oo7',yr:11,mod:'oo',dots:['oo-03'],type:'mcq',xp:30,
  prompt:'In a class diagram, a box lists "− ownerId : int" beneath its name. The minus sign means:',
  options:['The attribute is private — visible inside the class only','The attribute always stores a number that is strictly negative','The attribute is an operation, not stored data at all','The attribute has been inherited from a parent class above','The attribute is optional and may be omitted from diagrams'],answer:0,
  explain:'Class diagram notation: − marks private visibility, + marks public, and the line reads name : type. ownerId is an attribute (data), typed integer, and hidden behind the class interface — the notation companion of encapsulation.'},
 {id:'oo8',yr:11,mod:'oo',dots:['oo-04'],type:'mcq',xp:30,
  prompt:'A tangled legacy subsystem gets one simplified class placed in front of it; client code calls only that class and never touches the internals. This is:',
  options:['A stub — it returns fixed values until the real logic exists','The facade pattern — one entry point that hides all the mess','Top-down decomposition of the subsystem','Polymorphism via interfaces','A data dictionary entry for the subsystem'],answer:1,
  explain:'The facade pattern gives clients one easy entry point while the messy wiring stays hidden behind it — a standard design move when wrapping legacy or complex modules, and a deliberate act of abstraction in the OOP design process. A stub is a temporary placeholder, not a permanent interface.'},
 {id:'oo9',yr:11,mod:'oo',dots:['oo-05'],type:'mcq',xp:30,
  prompt:'Sending the message draw() to every object in a mixed list of shapes makes each object render differently. The precise mechanism is:',
  options:['The loop inspects each object’s type with IF statements before calling','The draw() name is overloaded at compile time across all classes','The list object itself is polymorphic and chooses each shape’s implementation','Each object’s own class decides which draw() runs — message-passing polymorphism','One shared draw() function definition mutates itself between the successive calls'],answer:3,
  explain:'One message — draw() — is sent to every object; the receiving object’s class resolves which implementation executes. There is no type inspection in the loop, and nothing is decided at compile time: resolution happens per object at the moment the message arrives.'},
 {id:'oo10',yr:11,mod:'oo',dots:['oo-06'],type:'mcq',xp:30,
  prompt:'A lookup over 10,000 records scans every row for each query. The syllabus-correct FIRST move to improve this is:',
  options:['Rename the variables for clarity first and hope the scan speeds up','Cache every query result unconditionally, even the ones never requested again later','Measure first, then improve the hot path by algorithm or data-structure change','Upgrade the CPU instead — software changes cannot fix scanning at all','Micro-optimise the comparison operator inside the loop for small constant-factor gains only'],answer:2,
  explain:'Optimisation discipline: the code must be correct first, then measured, then improved where the time actually goes — the hot path. Changing the algorithm/data structure moved the cost from O(n) to O(1) on average, orders of magnitude beyond any constant-factor tweak. Optimising before measuring is guessing.'},
 {id:'oo11',yr:11,mod:'oo',dots:['oo-07'],type:'mcq',xp:30,
  prompt:'Which pair of practices most directly supports a team editing one OOP codebase together?',
  options:['Version control with consistent, commented class interfaces','Long shared globals with single-letter variable names everywhere','Minifying the code before every single commit','A single shared branch with no history','Copy-pasting the classes into separate team forks'],answer:0,
  explain:'The syllabus’s collaborative supports are consistency, commenting, version control and feedback loops: teammates can review classes, share one codebase safely and recover from mistakes. Obfuscation, shared globals and history-free branching all work against exactly those supports.'},
 {id:'oo12',yr:11,mod:'oo',dots:['oo-08'],type:'mcq',xp:30,
  prompt:'The mainline is written first; the not-yet-implemented subroutines return fixed values so the flow can be tested end-to-end. These placeholders are:',
  options:['Drivers — harness code that calls the mainline so the placeholders can run','Stubs — clear mainline first, one logical task per real subroutine filled in later','Facades — pattern classes that wrap a messy subsystem behind one clean entry point','Breakpoints — deliberate pause markers that halt execution so state can be inspected','Watchpoints — debugging triggers that pause whenever a watched variable changes value'],answer:1,
  explain:'Stubs scaffold the structure: the clear mainline runs end-to-end against fixed returns while each real subroutine — one logical task each — is implemented afterwards. The practice implements the syllabus’s implementation discipline: write a clear mainline and give every subroutine exactly one job.'},
 {id:'oo13',yr:11,mod:'oo',dots:['oo-09'],type:'mcq',xp:30,
  prompt:'The testing levels, from smallest scope to largest, are:',
  options:['Unit → subsystem → system','System → unit → subsystem','Unit → system → subsystem','Subsystem → unit → system','Black box → grey box → white box'],answer:0,
  explain:'Unit tests exercise one module in isolation; subsystem tests exercise connected groups of modules; system tests exercise the whole product. Black/white/grey box are knowledge lenses, not levels — a unit test can be white box and a system test black box; the two classifications are independent.'},
 {id:'oo14',yr:11,mod:'oo',dots:['oo-09'],type:'mcq',xp:30,
  prompt:'A tester designs tests from the architecture and module interfaces WITHOUT reading the source code — and separately, the team defines the criteria quality will be judged against before building. The lens and the activity are:',
  options:['Black box testing; system testing','White box testing; unit testing','Grey box testing; quality assurance','Grey box testing; acceptance testing','White box testing; quality assurance'],answer:2,
  explain:'Black box is blind to internals; white box derives tests from the full source; grey box sits deliberately between — architecture and interfaces known, code unread. Quality assurance is the up-front definition of quality criteria and continual checking against requirements (including compliance and legislative obligations) — a process, not a test event.'},
/* ---- Year 11 · Programming Mechatronics ---- */
 {id:'me1',yr:11,mod:'me',dots:['me-01'],type:'mcq',xp:30,
  prompt:'A powered wheelchair controller is being designed for a user with limited hand movement. The FIRST design input is:',
  options:['The strongest available motors, all chosen before any user needs are known','The user’s needs, context and preferences — gathered directly from them','The maximum degrees of freedom the arm allows before any design work','The cheapest sensors on the market, bought in bulk up front','The wiring colour standard, locked in long before any needs analysis'],answer:1,
  explain:'Specialist requirements come from the end user — needs, environment and preferences drive the sensor, actuator and control choices, not raw capability. Testing only after building guarantees expensive redesign; capability-first design produces devices people cannot or will not use.'},
 {id:'me2',yr:11,mod:'me',dots:['me-02'],type:'mcq',xp:30,
  prompt:'The instruction SUB R2, 7 executes on a microcontroller. Which identification is precise?',
  options:['SUB is the opcode; R2 and 7 are the operands','SUB is an operand; R2 is the opcode','SUB is a register; 7 is the opcode','R2 is the opcode; SUB and 7 are operands','The instruction set is the opcode; SUB is the operand'],answer:0,
  explain:'The instruction set is the CPU’s vocabulary; each instruction names an operation (the opcode — here SUB) and supplies the operands it works on — the register R2 and the immediate value 7. Address and data registers are hardware storage locations, not parts of the instruction’s name.'},
 {id:'me3',yr:11,mod:'me',dots:['me-02'],type:'mcq',xp:30,
  prompt:'Compared with the general-purpose CPU in a desktop computer, a microcontroller is distinguished by:',
  options:['Higher clock speed and more RAM than any desktop CPU offers','A separate graphics card requirement sitting alongside the processor and memory','Processor, memory and input/output integrated on one chip for one embedded task','A completely different binary format that ordinary desktop compilers cannot even produce','Needing a full desktop operating system to boot before any code runs'],answer:2,
  explain:'A microcontroller bundles processor, memory and I/O on a single chip, built for one dedicated embedded job — exactly the target for closed loop control code in a mechatronic system. It is typically slower and smaller than a desktop CPU, not faster, and it runs the same broad classes of machine instructions.'},
 {id:'me4',yr:11,mod:'me',dots:['me-03'],type:'mcq',xp:30,
  prompt:'Sort the three components: ultrasonic rangefinder, servo motor, gripper.',
  options:['Sensor, actuator, end effector','Actuator, sensor, end effector','End effector, actuator, sensor','Sensor, end effector, actuator','Actuator, end effector, sensor'],answer:0,
  explain:'Sensors MEASURE the world (an ultrasonic rangefinder measures distance), actuators CREATE movement (a servo drives rotation), and end effectors are the tools at the arm’s end that touch and manipulate the work (a gripper). Mislabelling any of the three is the classic mechatronics taxonomy error.'},
 {id:'me5',yr:11,mod:'me',dots:['me-03'],type:'mcq',xp:30,
  prompt:'Which component CREATES motion rather than measuring it?',
  options:['A light-level sensor tracking the ambient brightness','A linear actuator extending a sorting arm','A gyroscopic sensor reading tilt and spin','A temperature sensor sampling the current heat','A proximity sensor detecting objects up close'],answer:1,
  explain:'Actuators convert control signals into physical action — extending, rotating, gripping. Every sensor in the list measures a physical quantity instead. The control loop needs both: the sensor reports, the controller decides, the actuator acts.'},
 {id:'me6',yr:11,mod:'me',dots:['me-04'],type:'mcq',xp:30,
  prompt:'A robot logs joint temperature and error codes every cycle, and a separate process later uses cycle times and power draw to tune performance. The two streams, respectively, are:',
  options:['Diagnostic data; optimisation data','Optimisation data; diagnostic data','Both diagnostic data','Both optimisation data','Both training data for supervised learning'],answer:0,
  explain:'Diagnostic data reports the system’s own health — currents, temperatures, error codes. Optimisation data tunes performance over time — cycle times, power draw, yields. Both must be validated at the source before use; mislabelling health data as optimisation feedstock corrupts the tuning.'},
 {id:'me7',yr:11,mod:'me',dots:['me-05'],type:'mcq',xp:30,
  prompt:'In a mechatronic wiring diagram, keeping data signal wires physically separated from high-current power lines primarily prevents:',
  options:['The battery overcharging on every recharge','The CPU overclocking itself beyond limits','Electrical noise corrupting the sensor readings','Actuators stalling under heavier mechanical load','Firmware corruption during every reflash cycle'],answer:2,
  explain:'High-current lines induce electrical noise in nearby signal wires, corrupting the small voltages sensors produce — the classic source of jittery readings and phantom triggers. Separating data and power paths, and budgeting power with headroom, is standard wiring practice.'},
 {id:'me8',yr:11,mod:'me',dots:['me-06'],type:'output',xp:50,lang:'py',
  prompt:'Desk-check this closed loop control algorithm. What is printed?',
  code:'setpoint = 21\ntemp = 26\nsteps = 0\nwhile temp > setpoint:\n    temp = temp - 2\n    steps = steps + 1\nprint(temp, steps)',
  options:['21 3','20 3','20 2','22 3','20 4'],answer:1,
  explain:'Trace it: 26 > 21 → 24 (1); 24 > 21 → 22 (2); 22 > 21 → 20 (3); 20 > 21 is false, so the loop stops. The controller overshoots BELOW the set point — 20, not 21 — because it corrects in steps of 2 and re-tests after each correction. Prints 20 3. A closed loop converges on the set point; step size decides whether it lands on it or oscillates past it.'},
 {id:'me9',yr:11,mod:'me',dots:['me-06'],type:'diagram',xp:55,diag:'ctrl1',
  prompt:'This is the control loop for a greenhouse cooling fan. Click the component that CLOSES the loop by measuring the actual output.',
  explain:'The sensor measures the process output (actual temperature) and feeds it back to the controller, which compares it against the set point and corrects the actuator. Remove the sensor and the system degrades into an open loop — action without feedback.'},
 {id:'me10',yr:11,mod:'me',dots:['me-06'],type:'mcq',xp:30,
  prompt:'Which system is the OPEN loop?',
  options:['An air-conditioner comparing the room temperature with the set target','A cruise control matching the measured road speed and adjusting itself','A greenhouse fan driven by readings from a temperature sensor','A toaster heating on a fixed timer, regardless of the browning'],answer:3,
  explain:'Open loop: action with NO measurement of the result — the toaster times out regardless of what happened to the bread. The other three all measure their output, compare against a target, and correct — the defining feedback of closed loop control.'},
 {id:'me11',yr:11,mod:'me',dots:['me-07'],type:'mcq',xp:30,
  prompt:'Unit tests for each component’s control algorithm run WITHOUT the hardware because they must prove the algorithm:',
  options:['Works correctly and repeats identically on every test run','Runs only on the real device under real loads','Removes any need for integration testing against the physical plant','Is always faster than an open loop controller overall','Needs no test data or expected outputs at all'],answer:0,
  explain:'Effectiveness AND repeatability: a control algorithm that behaves differently run to run is unusable, whatever its average performance. Running the algorithm in isolation — hardware-free — pins down its logic first; integration testing then checks it against the physical plant it will drive. Neither level replaces the other.'},
 {id:'me12',yr:11,mod:'me',dots:['me-07'],type:'output',xp:50,lang:'py',
  prompt:'This controller cools above 22 degrees and otherwise warms by one. Desk-check it: what is printed?',
  code:'temp = 24\nlog = []\nfor t in range(5):\n    if temp > 22:\n        temp = temp - 2\n    else:\n        temp = temp + 1\n    log.append(temp)\nprint(log)',
  options:['[22, 23, 21, 22]','[21, 22, 21, 22, 21]','[22, 23, 21, 22, 23]','[22, 23, 22, 23, 22]','[23, 22, 23, 22, 23]'],answer:2,
  explain:'Trace every pass: 24 > 22 → 22; then 22 > 22 is FALSE (strict comparison) → 23; 23 > 22 → 21; 21 → 22; 22 → 23. The log is [22, 23, 21, 22, 23]. The equality boundary at 22 decides the branch — reading > as >= is the classic desk-check slip — and the loop oscillates around the set point exactly as a bang-bang controller does.'},
/* ---- Year 12 · Secure Software Architecture ---- */
 {id:'ss1',yr:12,mod:'ss',dots:['ss-01'],type:'mcq',xp:30,
  prompt:'The enterprise case for investing in secure software development rests on:',
  options:['Guaranteeing the software will contain zero vulnerabilities across its lifetime','Protecting data and avoiding breach costs that dwarf prevention spending','Removing the need for testing phases and for security reviews','Making programs execute measurably faster on the same hardware','Lowering the monthly hosting bills for the deployed product'],answer:1,
  explain:'Security by design protects data, shrinks the attack surface and — critically for an enterprise — avoids the compounded cost of breaches: reputation, legal exposure and rework. Decisions made in design are cheap; the same decisions after release are expensive. No process guarantees zero vulnerabilities, which is precisely why the economics matter.'},
 {id:'ss2',yr:12,mod:'ss',dots:['ss-02'],type:'mcq',xp:30,
  prompt:'A ransomware attack encrypts a hospital’s records so staff cannot read them. Which security concept is DIRECTLY attacked?',
  options:['Availability','Confidentiality','Integrity','Authentication','Accountability'],answer:0,
  explain:'Availability keeps data reachable by those authorised to use it — encryption-by-attacker removes exactly that. Confidentiality would be breached if the data were EXPOSED; integrity if it were ALTERED. Naming the precise concept decides the correct control: backups and continuity restore availability.'},
 {id:'ss3',yr:12,mod:'ss',dots:['ss-02'],type:'mcq',xp:30,
  prompt:'A user logs in successfully but is denied the admin console; the system also records who attempted what, and when. The two security concepts demonstrated are:',
  options:['Authentication and encryption','Sanitisation and accountability','Authorisation and accountability','Authorisation and availability','Authentication and authorisation'],answer:2,
  explain:'Authentication already succeeded — the identity is proven. The denial is authorisation: what an authenticated identity may access. The record of who did what and when is accountability. Three distinct concepts: prove identity, gate access, attribute actions.'},
 {id:'ss4',yr:12,mod:'ss',dots:['ss-03'],type:'mcq',xp:30,
  prompt:'Which assignment of algorithm to role is correct?',
  options:['AES — asymmetric key exchange; RSA — symmetric hashing; SHA-256 — reversible encryption given the key','AES — password hashing; RSA — symmetric encryption; SHA-256 — asymmetric signing of messages','AES — symmetric encryption of bulk data; RSA — one-way hashing; SHA-256 — key exchange','AES — one-way digests of messages; RSA — symmetric encryption; SHA-256 — symmetric encryption of files','AES — symmetric bulk encryption; RSA — asymmetric key-pair encryption; SHA-256 — one-way hashing'],answer:4,
  explain:'AES is symmetric (one shared key, fast bulk encryption); RSA is asymmetric (public key encrypts, private key decrypts); SHA-256 is a hash — one-way, no key, no reverse. Mixing any two of these up is the standard cryptography trap; hashing is never reversible "if you hold the key", because there is no key.'},
 {id:'ss5',yr:12,mod:'ss',dots:['ss-03'],type:'mcq',xp:30,
  prompt:'Running untrusted code inside an isolated, restricted environment where it cannot touch the host system is:',
  options:['Sandboxing — a secure-design containment measure','Salting — it diversifies the input before hashing','SAST — static analysis of the code','Hardening by obfuscation','Patching'],answer:0,
  explain:'Sandboxing contains execution so a malicious or faulty component cannot reach the host — part of the security-by-design toolkit alongside cryptography. Salting hardens stored passwords; SAST inspects source; obfuscation hides code but does not contain it at runtime.'},
 {id:'ss6',yr:12,mod:'ss',dots:['ss-04'],type:'mcq',xp:30,
  prompt:'Which set matches the privacy-by-design principles?',
  options:['Reactive once complaints arrive; privacy bolted on after build; confidentiality as the default; protection during collection only; respect for shareholder value','Collect everything and filter later; privacy embedded into the data store; consent as the default; protection across the retention period; respect for partner interests','Proactive, never reactive; privacy embedded into the design; privacy as the default; protection throughout the complete lifecycle; respect for users’ privacy','Preventative only after launch; privacy embedded into the policy; security as the default; protection across the full lifecycle; respect for regulator expectations','Automated patching after audits; privacy embedded into the design; visibility as the default; protection while data is active; respect for user convenience'],answer:2,
  explain:'Privacy by design is proactive not reactive: privacy is embedded into the design from the start, defaults to sharing nothing, protects across the whole lifecycle, and treats respect for the user as a requirement rather than a patch. Every distractor mirrors the shape of the true set but swaps in one near-miss — confidentiality, consent, security or visibility as the default; collection-only or retention-only lifecycles; policy or data store instead of design. A set qualifies only when EVERY item is canonical, so audit each clause instead of trusting a familiar-looking one.'},
 {id:'ss7',yr:12,mod:'ss',dots:['ss-05'],type:'mcq',xp:30,
  prompt:'Which row of security-testing technique to method is entirely correct?',
  options:['SAST — probes the running application externally; DAST — inspects the source code without running it; penetration testing — a scheduled scan-and-report exercise; vulnerability assessment — authorised simulated attack','SAST — inspects source without executing; DAST — probes the running application externally; penetration testing — authorised attack exploiting weaknesses; vulnerability assessment — finding and rating weaknesses','All four are interchangeable names for one identical scan — whichever tool runs, the technique, the depth and the authorisation level make no difference to the finding','SAST — manual code review by the client; DAST — the compiler’s warning list; penetration testing — unit testing of security controls; vulnerability assessment — the project’s bug tracker','SAST — runtime memory analysis of processes; DAST — a static listing of functions; penetration testing — phishing campaigns only; vulnerability assessment — a review of firewall rules'],answer:1,
  explain:'The four techniques are distinct: SAST reads the code statically (catches injection patterns before anything runs); DAST attacks the live application externally; a penetration test actively exploits weaknesses under authorisation; a vulnerability assessment systematically finds and RATES weaknesses without necessarily exploiting them.'},
 {id:'ss8',yr:12,mod:'ss',dots:['ss-05'],type:'mcq',xp:30,
  prompt:'A penetration test is distinguished from a vulnerability assessment because it:',
  options:['Reads every line of source code statically without ever executing the application','Runs automatically after every commit and files a ticket for each warning','Avoids the live system entirely so production data can never be affected','Actively exploits flaws found, with permission and control, to show real impact','Removes the need for patching by proving which weaknesses cannot be exploited'],answer:3,
  explain:'An assessment finds and rates weaknesses; a penetration test goes further and EXPLOITS them — under authorisation and control — to show what an attacker would actually achieve. The exploitation step is the distinction, and it is why penetration tests require explicit permission and tight scope.'},
 {id:'ss9',yr:12,mod:'ss',dots:['ss-06'],type:'fix',xp:100,lang:'py',
  prompt:'Harden the intake gate. Spec: accept a string of digits whose integer value is 1–99 and return that integer; leading zeros are normalised (e.g. "007" → 7). Everything else returns None. It must never crash.',
  starter:'# INTAKE GATE :: quantity parser (unhardened)\n# Spec: accept a string of digits whose integer\n# value is 1-99 and return that integer.\n# Reject everything else with None. Never crash.\ndef parse_qty(s):\n    return int(s)',
  tests:[{label:'parse_qty("12") → 12',expr:'parse_qty("12")',expect:12},
   {label:'parse_qty("99") → 99',expr:'parse_qty("99")',expect:99},
   {label:'parse_qty("0") → None',expr:'parse_qty("0")',expect:null},
   {label:'parse_qty("100") → None',expr:'parse_qty("100")',expect:null},
   {label:'parse_qty("12x") → None',expr:'parse_qty("12x")',expect:null},
   {label:'parse_qty("") → None',expr:'parse_qty("")',expect:null},
   {label:'parse_qty(" 7") → None',expr:'parse_qty(" 7")',expect:null},
   {label:'parse_qty("007") → 7',expr:'parse_qty("007")',expect:7}],
  hints:['int() raises ValueError on anything it cannot parse — int("12x"), int("") — and TypeError on non-strings. The gate must never crash, so either screen the input BEFORE converting (allow-list) or wrap the conversion in try/except and return None in the handler.',
   'The sneaky test is " 7": int() happily strips surrounding whitespace, so a bare try/except alone would wrongly ACCEPT it. Screen the format explicitly — s.isdigit() is True only for non-empty all-digit strings, which rejects " 7", "12x" and "" in one shot. Guard the type too: parse_qty(7) must return None, not raise.',
   'Leading zeros need no work: int("007") is already 7. Convert, then range-check 1 <= n <= 99 so both "0" and "100" fall through to return None.'],
  explain:'Validate at the boundary with an allow-list: check the digit-only format BEFORE calling int() (which raises on bad input), then range-check 1–99 to reject both "0" and "100". Leading zeros are normalised by int(). Fail closed, never throw — int("12x") and int("") would otherwise crash the gate, and " 7" fails the digit test because a space is not a digit.'},
 {id:'ss10',yr:12,mod:'ss',dots:['ss-06'],type:'diagram',xp:55,diag:'arch2',
  prompt:'Injection faults keep surfacing in the ORDER SVC logs. Untrusted data enters the system somewhere. Click the node where input validation should FIRST be enforced.',
  explain:'The public API gateway is where untrusted data crosses the trust boundary into your network. Validate there — type, length, range, allow-list — before data ever reaches internal services or storage. Validating deep inside the network assumes an attacker is already inside.'},
 {id:'ss11',yr:12,mod:'ss',dots:['ss-06'],type:'mcq',xp:30,
  prompt:'Which pairing of defensive-handling technique to its precise action is correct?',
  options:['Validation — accept or reject input against rules; sanitisation — strip or neutralise dangerous content; error handling — fail closed with a generic message','Validation — rewrite unsafe input into a safer form; sanitisation — reject anything that fails the rules; error handling — suppress every failure silently','Validation — enforce the rules in the browser only; sanitisation — clean data before display only; error handling — an optional extra hardening stage','Validation — identical to sanitisation in effect; sanitisation — a synonym for validation; error handling — log the full details to every affected user','Validation — guarantee the data is genuinely accurate; sanitisation — guarantee the input is short enough; error handling — guarantee the process never crashes'],answer:0,
  explain:'Validation decides accept/reject against rules (type, length, range, allow-list); sanitisation cleans or neutralises content so it is safe for its destination; error handling fails closed — logs the detail server-side and shows a generic message. Neither validation nor sanitisation guarantees truthfulness, and both belong on the server, not only in the browser.'},
 {id:'ss12',yr:12,mod:'ss',dots:['ss-07'],type:'mcq',xp:30,
  prompt:'Which session-management set is the SECURE one?',
  options:['Tokens valid for a year; cookies without flags; logout leaves the token live','Short-lived tokens; Secure and HttpOnly cookie flags; tokens revoked at logout','Tokens passed in the URL; cookies shared across users; logout silently ignored','No tokens — IP address is the identity; cookies cleared weekly','Tokens stored client-side in plain text; session fixed at first login'],answer:1,
  explain:'Efficient, secure execution includes session management: short-lived tokens limit the window of theft, Secure/HttpOnly keep the cookie off scripts and plain HTTP, and true invalidation at logout makes "log out" mean something. An immortal token that survives logout is an impersonation waiting to happen.'},
 {id:'ss13',yr:12,mod:'ss',dots:['ss-07'],type:'mcq',xp:30,
  prompt:'The secure way to handle an unexpected exception in a web request handler is:',
  options:['Return the full stack trace so developers can debug the fault quickly','Swallow the exception quietly and continue processing with the partial data','Log detail server-side; return a generic message with correlation ID; fail closed','Crash the whole application process deliberately so the operators notice the failure','Email the raw exception text to every registered user of the service'],answer:2,
  explain:'Exception management fails securely: the detail goes to server-side logs for engineers, the user sees a generic message, and a correlation ID stitches the two together during an incident. Returned stack traces disclose internals (information disclosure); swallowed exceptions leave the system running on corrupted state.'},
 {id:'ss14',yr:12,mod:'ss',dots:['ss-08'],type:'mcq',xp:30,
  prompt:'A forum comment containing a script executes in EVERY visitor’s browser. Separately, a crafted URL makes its script run only for the person who clicks it. The pair of vulnerabilities, in order, is:',
  options:['Stored XSS; reflected XSS','Reflected XSS; stored XSS','Both stored XSS','Both reflected XSS','CSRF; XSS'],answer:0,
  explain:'The comment is SAVED and served to every visitor — stored XSS. The malicious payload lives in the crafted URL and fires only on the person who follows it — reflected XSS. Where the payload PERSISTS decides the name, and the persistence decides the blast radius.'},
 {id:'ss15',yr:12,mod:'ss',dots:['ss-08'],type:'mcq',xp:30,
  prompt:'CSRF is distinguished from XSS because CSRF:',
  options:['Injects attacker script into the pages the site serves to visitors','Abuses the victim’s existing session to send a request they never intended','Cracks stored password hashes by testing candidate secrets offline at leisure','Redirects a domain’s visitors by planting forged records in a DNS cache','Overwhelms a server by sending it more packets than it can answer'],answer:1,
  explain:'XSS runs attacker script in the victim’s browser; CSRF abuses the victim’s EXISTING authenticated session to fire a request the victim never intended — no script injection needed. The defences differ accordingly: output encoding against XSS, anti-forgery tokens and same-site cookies against CSRF.'},
 {id:'ss16',yr:12,mod:'ss',dots:['ss-08'],type:'mcq',xp:30,
  prompt:'Two threads both read a balance of $100, both pass the sufficiency check, and both withdraw — the account goes negative. Separately, a login endpoint accepts "admin" with any password after a timing tweak. The pair of flaws, in order, is:',
  options:['Race condition; broken authentication','Broken authentication; race condition','Invalid forwarding; XSS','XSS; CSRF','Both race conditions'],answer:0,
  explain:'The check-then-act sequence interleaves between threads, so both act on stale state — a race condition, fixed by locking or serialising the critical section. Accepting any password after manipulation is broken authentication — the credential check itself has failed. Two different classes: concurrent state corruption versus identity verification failure.'},
 {id:'ss17',yr:12,mod:'ss',dots:['ss-05','ss-06'],type:'log',xp:45,
  prompt:'A dynamic security test produced this report. Which finding should be remediated FIRST, and why?',
  log:'DAST REPORT :: portal.example (authenticated scan)\n\n  [CRITICAL] /login    accepts 1000-character passwords, no rate limit — credential stuffing unthrottled\n  [HIGH]     /search   query reflected into the page without encoding\n  [MED]      /account  session token exposed in the URL query string\n  [LOW]      server banner discloses framework version 2.4.1',
  options:['The LOW banner disclosure — quick wins build momentum for the wider remediation effort','The MED token exposure in URLs — privacy concerns outrank authentication strength','The CRITICAL login flaw — remotely exploitable now at scale; severity orders the queue','None of them — DAST findings are advisory until a penetration test confirms them','Re-scan the whole host for new findings before fixing anything at all'],answer:2,
  explain:'Severity and exploitability order the queue: unthrottled credential stuffing on the login path is exploitable right now, by anyone, at scale. The reflected XSS and the token-in-URL follow; the banner is cosmetic. And a DAST HIGH/CRITICAL is actioned, not merely noted — the report exists to drive fixes.'},
 {id:'ss18',yr:12,mod:'ss',dots:['ss-05','ss-06'],type:'log',xp:45,
  prompt:'A SAST scan ran before the release gate. Which finding indicates the injection class, and why does it block the release?',
  log:'SAST REPORT :: student-portal v2.1\n\n  [CRITICAL] SQL string concatenation in /results (lines 88-94)\n  [HIGH]     passwords compared with == instead of salted hash check\n  [MED]      debug endpoint /dump exposes table names\n\n policy: criticals must be fixed before the release gate',
  options:['The password comparison — a broken authentication flaw, so the policy gates the release on it','The concatenated SQL — user data can alter the query meaning, and the policy gates criticals','The debug endpoint — exposed table names are an injection payload, so it blocks the gate','None of them — SAST reports are advisory until a penetration test confirms every finding','All three equally — a static scanner cannot rank severity, so nothing gates the release'],answer:1,
  explain:'SAST flags the injection pattern statically: concatenated SQL lets input alter the query’s meaning — the SQL injection class — and the policy blocks the release gate on criticals. The password flaw is broken authentication and the exposed table names are information disclosure: both real, both lower severity, and neither is an injection class, so neither gates the release.'},
 {id:'ss19',yr:12,mod:'ss',dots:['ss-09'],type:'mcq',xp:30,
  prompt:'In Australia, the handling of personal information that an app collects is governed primarily by:',
  options:['The Copyright Act 1968, which protects creative works','The Privacy Act 1988 and the Australian Privacy Principles','The fair-use doctrine imported from United States case law','PCI-DSS — the payment-card industry standard for cardholder data','GDPR only, since Australia has no privacy statute'],answer:1,
  explain:'The Privacy Act 1988, with the Australian Privacy Principles, sets the legal obligations for collecting, holding, using and disclosing personal information — breaches carry notification duties and penalties. Copyright covers creative works, not personal data handling; PCI-DSS is a payment-industry standard, not the national privacy law.'},
 {id:'ss20',yr:12,mod:'ss',dots:['ss-09'],type:'mcq',xp:30,
  prompt:'A developer copies a premium theme’s code into a client’s site without a licence. The precise ramifications are:',
  options:['A privacy breach of personal data reportable under the Privacy Act 1988','No issue at all — code published on the internet is public','Copyright infringement of the author’s work — liability plus reputation damage','Patent infringement of the copied code, arising only once it is compiled','A concurrency race condition hidden in the theme’s client-side rendering logic'],answer:2,
  explain:'The theme is the author’s intellectual property: copying it without licence infringes copyright, exposing the developer and the client to legal and reputational damage. No personal data moved, so privacy law is untouched; compilation is irrelevant to copyright; and the fault is legal, not a concurrency bug.'},
 {id:'ss21',yr:12,mod:'ss',dots:['ss-06','ss-09'],type:'mcq',xp:30,
  prompt:'A public API receives untrusted JSON from the internet. Which defence sequence matches the syllabus?',
  options:['Trust the client-side validation alone; store with string concatenation; show stack traces to speed debugging','Sanitise only after storage; validate in the UI alone; log full errors publicly','Encrypt the JSON payload; skip validation entirely; trust the framework to be safe','Validate at the boundary; sanitise per destination; store via parameterised access; handle errors generically','Validate in the browser only; block the attacker’s IP address; rate-limit every endpoint'],answer:3,
  explain:'Defence is layered and ordered: untrusted data is validated where it crosses the trust boundary, sanitised for wherever it is heading (HTML, SQL, logs), stored through parameterised access so it can never change query meaning, and failures are handled generically. Client-side checks are convenience only — the server is the gate.'},
/* ---- Year 12 · Programming for the Web ---- */
 {id:'wb1',yr:12,mod:'wb',dots:['wb-01'],type:'mcq',xp:30,
  prompt:'Which feature set defines a progressive web app (PWA)?',
  options:['Requires an app-store review and a developer account before any release to users','Installs to the home screen, works offline, loads fast — standard web technologies','Runs only inside desktop browsers and never installs to a mobile home screen','Must be written in a compiled language and shipped as a native binary','Cannot access device capabilities such as the camera, offline storage or push notifications'],answer:1,
  explain:'PWAs are web applications that install to the home screen, work offline and start fast — the web reaching toward the native-app experience without an app-store gatekeeper, built from the same HTML/CSS/JS-and-server stack as any site.'},
 {id:'wb2',yr:12,mod:'wb',dots:['wb-03','wb-04'],type:'log',xp:45,
  prompt:'This capture was taken on the wire between a laptop and a login server. Which web security failure does it reveal?',
  log:'04:02:11 TCP 203.0.113.7:51422 → 198.51.100.4:80   [SYN]\n04:02:11 HTTP GET  /login                (plain)\n04:02:12 HTTP POST /login  user=priya&password=hunter2   ← visible in clear text\n04:02:14 HTTP 200 OK      (no TLS handshake observed)',
  options:['SQL injection — a crafted query payload inside the login POST','Cross-site request forgery — a forged request from another origin','Plain-text credentials — the POST travels over HTTP, not HTTPS','DNS cache poisoning — the name resolved to a bogus address','Race condition — two logins racing on one session token'],answer:2,
  explain:'The connection is to port 80 with no TLS handshake — plain HTTP — so anyone on the path reads the credentials exactly as typed. The fix is HTTPS: an SSL/TLS certificate and encryption of the whole channel. Nothing in the capture shows injected SQL, forged requests or poisoned DNS.'},
 {id:'wb3',yr:12,mod:'wb',dots:['wb-02'],type:'mcq',xp:30,
  prompt:'An IPv4 address is:',
  options:['32 bits written as four decimal octets, e.g. 203.0.113.7','128 bits written as eight colon-separated hexadecimal groups','64 bits written as six hexadecimal groups with colons','24 bits written as three decimal octets, e.g. 203.0.113','A 32-digit decimal number written with no separators'],answer:0,
  explain:'IPv4 gives each host a 32-bit address, conventionally written as four 8-bit octets in decimal with dots. The 128-bit eight-hex-group form is IPv6. Data moves across the internet in packets, each stamped with the source and destination IP so routers can forward it.'},
 {id:'wb4',yr:12,mod:'wb',dots:['wb-02'],type:'mcq',xp:30,
  prompt:'A DNS lookup that misses every cache follows which sequence?',
  options:['The browser asks the webserver for the page, which then quietly asks DNS on its behalf','The resolver asks a root server, the TLD server, then the authoritative server, caching the answer','The resolver asks the TLD server first, then the root server, and finally the authoritative server','The router assigns the machine a new IP address, and only then does the name resolve','The browser broadcasts the name to every server on the network until one of them answers'],answer:1,
  explain:'The DNS hierarchy is root → TLD → authoritative: the resolver descends it once, caches the answer, and every later lookup for that name reuses the cache until the record’s TTL expires. Typing a name into a browser begins with this system — names are for people, addresses are for routing.'},
 {id:'wb5',yr:12,mod:'wb',dots:['wb-03'],type:'mcq',xp:30,
  prompt:'Which row of protocol-to-default-port pairs is entirely correct?',
  options:['HTTP 443 · HTTPS 80 · FTP 22 · SFTP 21 · SMTP 110 · POP3 25 · IMAP 143','HTTP 80 · HTTPS 443 · FTP 25 · SMTP 21 · POP3 110 · IMAP 143 · SFTP 22','HTTP 80 · HTTPS 443 · FTP 21 · SFTP 22 · SMTP 25 · POP3 110 · IMAP 143','HTTP 8080 · HTTPS 443 · FTP 21 · SFTP 25 · SMTP 22 · POP3 110 · IMAP 143','SMTP 110 · POP3 25 · IMAP 443 · HTTP 80 · HTTPS 8080'],answer:2,
  explain:'The pairs to know cold: HTTP 80, HTTPS 443, FTP 21, SFTP 22, SMTP 25, POP3 110, IMAP 143. Every distractor swaps exactly one — the exam difference between knowing the table and recognising it.'},
 {id:'wb6',yr:12,mod:'wb',dots:['wb-03'],type:'mcq',xp:30,
  prompt:'A mail client SENDS a message, and later RETRIEVES the replies. The protocols used, in order, are:',
  options:['SMTP to send; IMAP or POP3 to retrieve','IMAP to send; SMTP to retrieve the replies','POP3 to send; SMTP to retrieve the replies','SMTP to send; SMTP again to retrieve replies','HTTP to send; FTP to retrieve the mail'],answer:0,
  explain:'SMTP pushes mail out to the server; POP3 and IMAP pull it down to the client — IMAP keeps it on the server across devices, POP3 downloads it. Sending and retrieving are different jobs on different protocols and ports, which is why the port table lists them separately.'},
 {id:'wb7',yr:12,mod:'wb',dots:['wb-04'],type:'mcq',xp:30,
  prompt:'An SSL/TLS certificate, issued by a certificate authority, primarily:',
  options:['Encrypts the server’s database files at rest, protecting all stored records from offline theft','Hashes every form field before it is ever sent and stores only the digest','Guarantees that the live site contains no XSS, SQL injection or other code flaws','Replaces the need for strong passwords and lockouts on every account the server holds','Binds a domain’s public key to its verified identity, enabling HTTPS and server authentication'],answer:4,
  explain:'The certificate is the trust anchor of HTTPS: a certificate authority vouches that this public key belongs to this domain, so the browser can encrypt the channel and know it is talking to the real server — not an impostor. It says nothing about database-at-rest encryption, code quality or password policy.'},
 {id:'wb8',yr:12,mod:'wb',dots:['wb-04'],type:'mcq',xp:30,
  prompt:'Which trio is precisely correct?',
  options:['Hash — one-way and keyless; encryption — reversible with a key; signature — the document’s hash encrypted with the signer’s PRIVATE key','Hash — two-way with a key; encryption — one-way with no key at all; signature — hash encrypted with the signer’s public key','Hash — one-way with no key; encryption — reversible with a key; signature — the document’s hash encrypted with the signer’s PUBLIC key','Hash — reversible with enough effort; encryption — one-way with a shared key; signature — a symmetric-only construction using one shared secret','All three are one identical cryptographic operation — hash, encryption and digital signature differ in their names alone and nothing else'],answer:0,
  explain:'A hash is one-way with no key. Encryption is reversible with the right key. A digital signature is the hash of the document encrypted with the signer’s PRIVATE key — the recipient decrypts it with the public key and compares hashes, proving both integrity and origin. C and D are the near-misses: signing uses the private key, never the public one.'},
 {id:'wb9',yr:12,mod:'wb',dots:['wb-04'],type:'mcq',xp:30,
  prompt:'Data readable without any key is ____; data scrambled so it is unreadable without the key is ____.',
  options:['cipher text; plain text','plain text; cipher text','a hash; a digest','encoded; hashed','compressed; signed'],answer:1,
  explain:'Plain text is readable as-is; cipher text is the encrypted form, unreadable without the key. A hash is not "readable later" at all — it is a one-way fingerprint. The plain/cipher pair is the vocabulary of every encryption question on this paper.'},
 {id:'wb10',yr:12,mod:'wb',dots:['wb-05'],type:'mcq',xp:30,
  prompt:'A streaming service records what you watched, when, and for how long, then mines that record to recommend titles and to provision capacity. The recorded activity is best described as:',
  options:['Cipher text — the record is encrypted before mining and unreadable','Metadata — data about data, mined to drive recommendations and planning','Diagnostic data — telemetry from a factory robot, not from viewers','A digital signature — tamper-proof evidence the record was never altered','The content itself — the streamed shows and films being watched'],answer:1,
  explain:'Metadata is the who/when/how-long wrapper around the content — data about data. Big data architecture is built on mining it: recommendations, forecasting, streaming management. The content itself is the video; the record of your viewing is the metadata layer.'},
 {id:'wb11',yr:12,mod:'wb',dots:['wb-06'],type:'mcq',xp:30,
  prompt:'Which set lists concerns of the W3C?',
  options:['Telecommunication cable standards, radio spectrum licensing and satellite orbit allocations','Browser search defaults, commercial hosting prices and advertising partnerships','Accessibility, internationalisation, web security, user privacy and machine-readable data','Operating system kernels, device drivers and processor instruction architectures','Domain name auction prices, registrar fees and aftermarket resale commissions'],answer:2,
  explain:'The World Wide Web Consortium sets web standards: accessibility (its Web Accessibility Initiative), internationalisation so the web works across languages, security, privacy, and machine-readable data that lets programs — not just people — use the web. It does not regulate cables, kernels or prices.'},
 {id:'wb12',yr:12,mod:'wb',dots:['wb-06'],type:'mcq',xp:30,
  prompt:'The Web Accessibility Initiative (WAI) exists to:',
  options:['Set the encryption standards used by HTTPS and other transport protocols','Develop guidelines so the web is usable by people with disability','Certify browsers for rendering speed and compliance before their public release','Regulate the commercial registration, resale and auctioning of internet domain names','Translate every page on the web into English for readers abroad'],answer:1,
  explain:'The WAI is the W3C’s accessibility arm: its guidelines — sufficient contrast, full keyboard operability, labels for assistive technologies — make the web inclusive by design. That guidance is also a legal baseline in Australia, not an optional extra.'},
 {id:'wb13',yr:12,mod:'wb',dots:['wb-07'],type:'mcq',xp:30,
  prompt:'An online store keeps a cart across visits, takes payments, and shows live stock. Which duty belongs to the BACK end?',
  options:['Drawing and animating the cart buttons through their hover, focus and pressed interaction states','Highlighting invalid fields inside the browser the instant the user types a character','Re-validating every submission, processing the payment and querying the database for live stock','Laying out the responsive cart page with CSS grid, flexbox and media queries','Showing placeholder text in the empty search box before the user starts typing'],answer:2,
  explain:'The front end renders and interacts in the browser; the back end is the trust boundary — it re-validates (the browser belongs to the user and can be bypassed), moves money, and queries the database. Every duty that must be ENFORCED, rather than merely displayed, is back-end duty.'},
 {id:'wb14',yr:12,mod:'wb',dots:['wb-07'],type:'mcq',xp:30,
  prompt:'When is a non-SQL (document) database the better fit?',
  options:['When flexible, nested documents must scale massively and fixed table schemas fit poorly','When multi-table transactions with strict referential integrity and structured joins dominate the workload','When the data is a small, rigidly structured ledger with fixed relationships','Never — SQL is always the correct choice whatever the workload demands','When the team simply wants to avoid modelling the data at all'],answer:0,
  explain:'Non-SQL stores trade the rigid relational schema for flexibility and horizontal scale — ideal for nested, evolving documents. Relational SQL databases remain the tool where referential integrity and structured joins dominate. "No modelling at all" is a trap: the schema moves into the application either way.'},
 {id:'wb15',yr:12,mod:'wb',dots:['wb-08'],type:'mcq',xp:30,
  prompt:'A team restyles a 40-page site by editing ONE stylesheet, and every page updates instantly. This demonstrates:',
  options:['Faster database queries — one shared stylesheet lightens the query load on every single page','Encrypted transport — the shared stylesheet secures the connection between site and device at once','The separation of style from structure — one source of truth for every page\'s appearance','Table joins in the CSS — the stylesheet merges content drawn from your database tables','Server-side rendering — the server rebuilds every page the moment the stylesheet file is changed'],answer:2,
  explain:'CSS exists to separate presentation from structure: one stylesheet is the single source of truth for appearance, so consistency is automatic and per-device adaptation is centralised. No query, certificate or join is involved — the benefit is architectural.'},
 {id:'wb16',yr:12,mod:'wb',dots:['wb-09'],type:'diagram',xp:55,diag:'arch3',
  prompt:'A student submits the login form. Click the node where webserver software FIRST receives and processes the request on the server side.',
  explain:'The webserver software accepts the HTTP request first, then hands it to the web framework, whose objects and libraries interface with databases and caches — the back-end request path in one click.'},
 {id:'wb17',yr:12,mod:'wb',dots:['wb-09'],type:'output',xp:50,lang:'sql',
  prompt:'Using the mini database in the comments, what result table does this query produce?',
  code:'-- students(student_id, name)\n--   (1,\'Amelia\')  (2,\'Jack\')  (3,\'Priya\')  (4,\'Marco\')\n-- enrolments(student_id, course_id, mark)\n--   (1,\'SWE\',88) (1,\'MTH\',45) (3,\'SWE\',91)\n--   (3,\'MTH\',74) (4,\'SWE\',62)\n\nSELECT students.name, enrolments.course_id, enrolments.mark\nFROM students\nLEFT JOIN enrolments ON students.student_id = enrolments.student_id\nWHERE enrolments.mark IS NULL OR enrolments.mark >= 80\nORDER BY students.name;',
  options:['Amelia · SWE · 88, then Jack · NULL · NULL, then Priya · SWE · 91','Amelia · SWE · 88, then Priya · SWE · 91','Amelia · SWE · 88, then Jack · NULL · NULL, then Priya · SWE · 91, then Marco · SWE · 62','Jack · NULL · NULL, then Amelia · SWE · 88, then Priya · SWE · 91','Amelia · SWE · 88, then Amelia · MTH · 45, then Priya · SWE · 91'],answer:0,
  explain:'LEFT JOIN keeps every student; Jack has no enrolment, so his row fills with NULLs and survives the IS NULL test. Amelia’s SWE 88 and Priya’s SWE 91 clear the mark >= 80 filter; Amelia’s MTH 45, Priya’s MTH 74 and Marco’s SWE 62 do not. ORDER BY name sorts Amelia, Jack, Priya. The distractors are exactly the four classic slips: dropping the NULL row (inner-join thinking), ignoring the WHERE, ignoring the ORDER BY, and inverting the comparison.'},
 {id:'wb18',yr:12,mod:'wb',dots:['wb-09','wb-07'],type:'fix',xp:100,lang:'sql',
  prompt:'The report should list each course title with its average mark, but ONLY courses averaging 75 or more. The intern’s version is rejected by the database. Patch it so the query runs and returns the correct table.',
  starter:'-- DATA :: courses(course_id, title)\n--   (\'SWE\', \'Software Engineering\')  (\'MTH\', \'Mathematics\')\n-- enrolments(course_id, mark)\n--   (SWE, 88) (SWE, 92) (SWE, 70) (SWE, 86) (MTH, 74) (MTH, 58)\n\nSELECT courses.title, AVG(enrolments.mark)\nFROM courses\nJOIN enrolments ON courses.course_id = enrolments.course_id\nWHERE AVG(enrolments.mark) >= 75\nGROUP BY courses.title;',
  tests:[{label:'RESULT == one row: Software Engineering · 84',expect:{rows:[['Software Engineering',84]]}}],
  db:{courses:{cols:['course_id','title'],rows:[['SWE','Software Engineering'],['MTH','Mathematics']]},
      enrolments:{cols:['course_id','mark'],rows:[['SWE',88],['SWE',92],['SWE',70],['SWE',86],['MTH',74],['MTH',58]]}},
  explain:'Aggregates cannot appear in WHERE — it filters individual rows before any grouping exists, so the database rejects AVG there. Move the condition to HAVING, which filters whole groups after aggregation. Software Engineering averages (88+92+70+86)/4 = 84 and survives the threshold; Mathematics averages 66 and is filtered out.'},
 {id:'wb19',yr:12,mod:'wb',dots:['wb-09'],type:'output',xp:50,lang:'sql',
  prompt:'Using the enrolment data in the comments, what does this query return?',
  code:'-- enrolments(student_id, course_id, mark)\n--   (1,\'SWE\',88) (2,\'SWE\',62) (3,\'SWE\',90)\n--   (4,\'MTH\',74) (5,\'MTH\',46) (6,\'SCI\',91)\n\nSELECT course_id, COUNT(*), AVG(mark)\nFROM enrolments\nGROUP BY course_id\nHAVING COUNT(*) >= 2 AND AVG(mark) > 70\nORDER BY course_id;',
  options:['MTH · 2 · 60','SWE · 3 · 80','SCI · 1 · 91','SWE · 2 · 89','No rows — aggregates belong in WHERE'],answer:1,
  explain:'GROUP BY forms one group per course: SWE has 3 rows averaging (88+62+90)/3 = 80, MTH has 2 averaging 60, SCI has 1 averaging 91. HAVING filters the GROUPS: MTH fails the average test, SCI fails the count test — only SWE survives, sorted last-to-first irrelevant with one row. WHERE could never see COUNT or AVG; HAVING is the group filter.'},
 {id:'wb20',yr:12,mod:'wb',dots:['wb-09'],type:'mcq',xp:30,
  prompt:'A browser POSTs a login form. The server-side order of first contact is:',
  options:['Webserver software → web framework → database — the framework\'s objects and libraries query it','Database → web framework → webserver — the data layer fields the request first','Web framework → webserver software → database — the framework fields the request first','Webserver software → database → web framework — storage is consulted before the framework','Web framework → database → webserver software — the webserver responds last, after the data layer'],answer:0,
  explain:'The webserver software (accepting HTTP) is the first server-side stop; it dispatches to the web framework, whose objects and libraries interface with the database. Back-end development means building on that path — webserver, framework, data layer — in that order.'},
 {id:'wb21',yr:12,mod:'wb',dots:['wb-07'],type:'mcq',xp:30,
  prompt:'Choosing an ORM over hand-written SQL trades:',
  options:['Correctness for raw speed — ORMs cannot even express a table join','Faster development and database portability for less fine-grained control over queries','Nothing whatsoever — an ORM is strictly superior in every single dimension','Portability traded for correctness — plain SQL is never portable at all','Security traded for flexibility — ORMs make parameterised queries completely impossible'],answer:1,
  explain:'Object-relational mapping lets developers think in objects instead of SQL and moves more easily between database engines — but the generated queries surrender the precise control (and sometimes the performance) of hand-written SQL. ORMs express joins fine and pair with parameterisation; the real trade is control versus convenience.'},
 {id:'wb22',yr:12,mod:'wb',dots:['wb-09'],type:'mcq',xp:30,
  prompt:'students.student_id and enrolments.student_id. Which statement is precise?',
  options:['Both columns are the primary keys of their own tables, so each one uniquely identifies its row','The foreign key lives in students, referencing enrolments — the child table carries the reference back toward its parent','students.student_id is the primary key; enrolments.student_id is its foreign key; a no-ON join is a cartesian product','A join without an ON condition is a syntax error that the database refuses to even run','A foreign key must hold unique values in its own table, exactly like a primary key must'],answer:2,
  explain:'The primary key uniquely identifies each student; the foreign key in enrolments references it and enforces the relationship. A condition-less join is legal SQL and produces the cartesian product — 4 students × 5 enrolments = 20 rows of every pairing — which is why the missing-ON bug multiplies row counts. A foreign key routinely repeats (one student, many enrolments); uniqueness is the PRIMARY key’s job.'},
 {id:'wb23',yr:12,mod:'wb',dots:['wb-10'],type:'mcq',xp:30,
  prompt:'Which pairing of UI/UX principle to its effect is correct?',
  options:['Tiny fonts — more content per screen; clashing colours — user attention; deeply nested menus — engagement','Autoplaying background audio — a modern, dynamic feel for visitors; hidden input labels — clean visual minimalism','High contrast ratios — battery saving across long viewing sessions; deep navigation menus — much better search rankings','Font choice — smaller database storage requirements; colour depth settings — less bandwidth consumed per visit','Consistent font hierarchy — reading order; colour contrast — legibility; predictable navigation — low cognitive load'],answer:4,
  explain:'UI/UX design of font, colour, audio, video and navigation serves the user: hierarchy tells the eye where to go, contrast keeps text legible (a measured accessibility requirement, not a battery trick), and predictable navigation keeps cognitive load low. Every distractor optimises for the site, not the person.'},
 {id:'wb24',yr:12,mod:'wb',dots:['wb-10'],type:'mcq',xp:30,
  prompt:'For an inclusive PWA, contrast ratios, keyboard-only navigation and screen-reader labels are:',
  options:['Accessibility requirements designed in from the start, never a post-launch patch','Optional extras to add if time remains once the site has shipped','Back-end database concerns, handled entirely by the storage layer\'s schema rules','Server configuration settings applied once in the web server\'s config files','Requirements that apply only to government websites, not commercial projects'],answer:0,
  explain:'Accessibility and inclusivity are UI/UX design inputs — WAI guidance applied while designing font, colour, audio, video and navigation. Retrofitting them after launch costs multiples and ships exclusion in the meantime; and the obligation is not limited to any one class of site.'},
 {id:'wb25',yr:12,mod:'wb',dots:['wb-09'],type:'output',xp:50,lang:'sql',
  prompt:'Using the course table in the comments, what does this query return?',
  code:'-- courses(course_id, title)\n--   (\'MTH\',\'Mathematics\')  (\'PHY\',\'Physics\')\n--   (\'SWE\',\'Software Engineering\')  (\'STA\',\'Software Design\')\n--   (\'MAR\',\'Marine Studies\')\n\nSELECT DISTINCT title\nFROM courses\nWHERE title LIKE \'S%\'\nORDER BY title\nLIMIT 2;',
  options:['Software Design, then Software Engineering','Software Engineering, then Software Design','Software Design only — DISTINCT collapses the two Software titles into one','All five titles — LIKE \'S%\' matches every row','Software Design, Software Engineering, then Software Engineering again — duplicates retained'],answer:0,
  explain:'LIKE \'S%\' matches titles STARTING with S — the two Software courses (SWE and STA); Mathematics, Physics and Marine Studies fail the pattern. DISTINCT removes duplicates (there are none here), ORDER BY title sorts ascending, and LIMIT 2 caps the output at the first two rows. "S%" anchors the S to the start — the pattern for "contains S" would be \'%S%\'.'},
/* ---- Year 12 · Software Automation ---- */
 {id:'au1',yr:12,mod:'au',dots:['au-01'],type:'mcq',xp:30,
  prompt:'Which statement draws the precise distinction between AI and machine learning?',
  options:['ML is the broad field of thinking machines; AI is merely the narrow sub-approach that learns from data','AI and ML are simply two interchangeable names for exactly the same broad field of intelligent machine behaviour','AI is the broad field of machines performing tasks needing intelligence; ML is the sub-approach learning from data','AI always requires a physical robot body — genuine machine intelligence is impossible without hardware to embody it','ML works without any training data at all — hand-written rules alone drive every improvement in its performance'],answer:2,
  explain:'AI is the umbrella: machines performing tasks that need intelligence. Machine learning is one approach under it — improving performance by learning from data rather than by following explicitly programmed rules. No robot body is required, and ML is defined BY its use of data.'},
 {id:'au2',yr:12,mod:'au',dots:['au-01'],type:'mcq',xp:30,
  prompt:'Match each automation to its definition:',
  options:['RPA — re-engineers whole business processes from end to end; BPA — mimics every human interface click; DevOps — automates the build-deploy pipeline','RPA — mimics a human operating an interface click by click; BPA — re-engineers whole business processes; DevOps — automates the delivery pipeline','RPA — automates the build-test-deploy pipeline; BPA — mimics every human interface click; DevOps — re-engineers whole business processes from end to end','RPA — identical to BPA and DevOps; BPA — identical to RPA and DevOps; DevOps — identical to RPA and BPA','RPA — physical factory robots on the assembly line; BPA — physical office robots at desks; DevOps — physical warehouse robots in aisles'],answer:1,
  explain:'Robotic process automation operates the interface exactly as a human would — click by click on the same screens. Business process automation re-engineers the entire process flow. DevOps automates the software delivery pipeline itself. None of them implies a physical robot — the "robot" in RPA is software.'},
 {id:'au3',yr:12,mod:'au',dots:['au-02'],type:'mcq',xp:30,
  prompt:'Four scenarios: (1) thousands of emails already labelled spam or not-spam; (2) invoices grouped into clusters with no labels at all; (3) an agent rewarded for good moves and penalised for bad ones; (4) 5% of a photo set labelled, with labels propagated to the rest. The training models, in order, are:',
  options:['supervised, reinforcement, unsupervised, semi-supervised','unsupervised, supervised, semi-supervised, reinforcement','semi-supervised, unsupervised, supervised, reinforcement','supervised, unsupervised, reinforcement, semi-supervised','reinforcement, supervised, unsupervised, semi-supervised'],answer:3,
  explain:'Labelled examples → supervised. Structure in unlabelled data → unsupervised. Reward and penalty through interaction → reinforcement. A small labelled seed with labels propagated through a large unlabelled set → semi-supervised. Four models, four precise triggers — the examinable skill is matching the scenario to the model.'},
 {id:'au4',yr:12,mod:'au',dots:['au-02'],type:'mcq',xp:30,
  prompt:'The defining ingredient that separates supervised from unsupervised learning is:',
  options:['Labelled examples — inputs paired with known correct outputs','A neural network — one model family among many','Rewards and penalties — the engine of reinforcement learning','A larger dataset — sheer volume of collected examples','A decision tree — one more explainable model family'],answer:0,
  explain:'Supervised learning needs labelled data — inputs with known correct outputs to learn from. Unsupervised learning finds structure in unlabelled data. The model family, the size of the dataset and the presence of rewards are all secondary to that one ingredient.'},
 {id:'au5',yr:12,mod:'au',dots:['au-03'],type:'mcq',xp:30,
  prompt:'A clinic needs a model whose decisions clinicians can inspect, audit and explain. The better choice, and the reason, are:',
  options:['A neural network — always more accurate than a tree and always explainable through its weighted layers','A decision tree — every path is a readable chain of threshold rules, not opaque neural layers','Either — both models are equally transparent, so clinicians can inspect and audit either choice with equal ease','Neither — explanation is impossible for any machine learning model, so auditability remains out of reach altogether','A decision tree — chosen because it needs no training data at all to become auditable'],answer:1,
  explain:'A decision tree exposes its reasoning: each branch is a threshold question a clinician can read and challenge. A neural network may out-accuracy it, but its reasoning is buried in weighted layers — explainability is a design criterion, and it must be chosen, not assumed.'},
 {id:'au6',yr:12,mod:'au',dots:['au-03'],type:'output',xp:50,lang:'py',
  prompt:'This Python code encodes a tiny decision tree. What is printed?',
  code:'def classify(hours, attendance):\n    if hours >= 10:\n        if attendance >= 80:\n            return "distinction"\n        return "credit"\n    if attendance >= 90:\n        return "credit"\n    return "pass"\n\nprint(classify(12, 75), classify(8, 95), classify(15, 90))',
  options:['credit credit distinction','distinction credit distinction','credit pass distinction','pass credit distinction','credit credit pass'],answer:0,
  explain:'The tree tests hours FIRST: 12 ≥ 10 → attendance 75 < 80 → leaf "credit". 8 < 10 → attendance 95 ≥ 90 → "credit". 15 ≥ 10 and 90 ≥ 80 → "distinction". Branch order is everything: the attendance ≥ 90 path is only reachable when hours < 10 — a leaf you cannot reach stays a leaf.'},
 {id:'au7',yr:12,mod:'au',dots:['au-04'],type:'mcq',xp:30,
  prompt:'Predicting a student’s exam MARK (0–100) versus predicting PASS/FAIL. The matched pair of algorithms is:',
  options:['Logistic regression for both — regression coefficients produce a numeric prediction either time','Linear regression for both — pass/fail reduces to a fitted number','Linear regression fits the numeric mark; logistic regression fits the pass/fail probability','K-nearest neighbour predicts the mark; linear regression predicts the pass/fail outcome','A decision tree predicts the mark; plain regression cannot classify outcomes at all'],answer:2,
  explain:'Regression models predicting numeric values use linear regression; categorical yes/no outcomes call for logistic regression, which outputs the probability of the class. KNN can do either but is not the paired answer here — and regression DOES classify, via the logistic variant.'},
 {id:'au8',yr:12,mod:'au',dots:['au-04'],type:'output',xp:50,lang:'py',
  prompt:'This linear regression model predicts a mark from hours studied. What is printed?',
  code:'def predict(hours):\n    return 2 * hours + 5\n\ntotal = 0\nfor h in [1, 3, 6]:\n    total = total + predict(h)\nprint(total)',
  options:['33','35','34','36','70'],answer:1,
  explain:'The fitted line is mark = 2 × hours + 5: predictions 7, 11 and 17 for 1, 3 and 6 hours. The accumulator sums 7 + 11 + 17 = 35. A regression model is just a function — evaluating it and summing the outputs is all this fragment does.'},
 {id:'au9',yr:12,mod:'au',dots:['au-04'],type:'output',xp:50,lang:'py',
  prompt:'This code performs a 1-dimensional k-nearest-neighbour vote (k = 3) for the point 6. What is printed?',
  code:'points = [[1, "A"], [2, "B"], [4, "B"], [7, "A"], [8, "B"], [11, "A"]]\nnew = 6\nk = 3\n\ndists = []\nfor p in points:\n    dists.append([abs(p[0] - new), p[1]])\ndists.sort()\n\nvotes = []\nfor d in dists[:k]:\n    votes.append(d[1])\nprint(votes)',
  options:["['B', 'B', 'A'] — majority B","['B', 'A', 'B'] — majority B","['A', 'A', 'B'] — majority A","['A', 'B', 'B'] — majority B","['B', 'A', 'B'] — majority A"],answer:3,
  explain:'Distances from 6: |1−6| = 5 (A), |2−6| = 4 (B), |4−6| = 2 (B), |7−6| = 1 (A), |8−6| = 3 (B), |11−6| = 6 (A). Sorted ascending: [1 A], [2 B], [3 B], [4 B], [5 A], [6 A] — the k = 3 nearest are A, B, B, so the majority class is B. KNN is exactly this: measure, sort, vote.'},
 {id:'au10',yr:12,mod:'au',dots:['au-04'],type:'mcq',xp:30,
  prompt:'K-nearest neighbour is called a LAZY learner because:',
  options:['It trains for fewer epochs than the other models require up front','It stores the training set and defers all work until classification time','It skips the distance calculation entirely when classifying each new example','It cannot be used for regression tasks — only for classification problems','It discards the training data once a model has been fitted'],answer:1,
  explain:'KNN fits nothing up front: it memorises the training examples and, when asked to classify, measures distances and takes a majority vote of the k nearest. All the computation happens at prediction time — the mirror image of eager learners, which fit a model first and predict cheaply afterwards.'},
 {id:'au11',yr:12,mod:'au',dots:['au-05'],type:'mcq',xp:30,
  prompt:'Match each application of ML to its task:',
  options:['Face unlock — forecasting; phone assistant — image recognition; next quarter’s sales — virtual personal assistant','Next quarter’s sales — forecasting; face unlock — image recognition; phone assistant — virtual personal assistant','All three scenarios are image recognition tasks, merely applied to three different kinds of input','Face unlock — virtual personal assistant; next quarter’s sales — image recognition; phone assistant — forecasting','Forecasting — image recognition; face unlock — data analysis; phone assistant — forecasting next quarter'],answer:1,
  explain:'The syllabus’s application areas are data analysis and forecasting, virtual personal assistants, and image recognition — each maps onto exactly one of the scenarios. Matching the task to the application area is the assessed skill, not naming the cleverest model.'},
 {id:'au12',yr:12,mod:'au',dots:['au-05'],type:'mcq',xp:30,
  prompt:'A virtual personal assistant turns speech into text, interprets the request, and answers aloud. The enabling field pair is:',
  options:['Natural language processing plus speech recognition and synthesis — a standard ML application area','Computer vision plus robotics — the standard hardware stack for embodied, physical robot assistants','Blockchain plus edge computing — the trendy infrastructure pairing for always-on distributed network services','Linear regression plus hashing — a numeric fitting and data-lookup pairing of algorithmic techniques','RPA plus version control — automating interface clicks and code commits behind the scenes'],answer:0,
  explain:'Understanding and producing human language is natural language processing; hearing and speaking it is speech recognition and synthesis. Together they make the assistant — the classic virtual personal assistant stack, and a named ML application area in the syllabus.'},
 {id:'au13',yr:12,mod:'au',dots:['au-06'],type:'mcq',xp:30,
  prompt:'The documented employment impact of automation is:',
  options:['All jobs disappear uniformly across every industry and every skill level within a single decade','Employment changes its nature and skills — routine tasks decline while technical and design roles grow','The required skills stay exactly the same across every role, every industry and every year','Only creative and artistic jobs are affected, and only inside the media and design industries','Employment effects stop at the factory gate, never reaching offices, shops or any other service industry'],answer:1,
  explain:'Automation shifts the skill mix rather than simply deleting work: routine tasks are automated while technical, supervisory and design roles expand around them. Safety, opportunity for people with disability, waste and the distribution of wealth are the other documented impact lenses — the effect is structural, not uniform.'},
 {id:'au14',yr:12,mod:'au',dots:['au-06'],type:'mcq',xp:30,
  prompt:'Which set matches the syllabus impact lenses for automation to their concerns?',
  options:['Individual — cloud hosting cost overruns; society — compiler version churn everywhere; environment — IDE colour theme choices','Individual — salary changes only; society — nothing measurable beyond salary itself; environment — nothing measurable at all','Individual — user screen time; society — shifting technology trends; environment — keyboards and their eventual e-waste disposal','Individual — nothing documented anywhere; society — nothing documented either; environment — no documented impacts of any kind','Individual — safety and opportunity for people with disability; society — wealth distribution; environment — waste and energy'],answer:4,
  explain:'The syllabus lenses: automation improves safety and creates opportunity for people with disability (individual), shifts how wealth and work are distributed (society), and carries environmental costs in waste and energy (environment). Impacts cut both ways — that is what makes them assessable.'},
 {id:'au15',yr:12,mod:'au',dots:['au-07'],type:'mcq',xp:30,
  prompt:'Which distinction between the two bias sources is precise?',
  options:['Human bias — a phenomenon confined to hiring and lending decisions; dataset bias — a phenomenon confined to image recognition sets','Human bias — exactly the same thing as dataset bias; dataset bias — exactly the same thing as human bias','Dataset bias — a problem that vanishes by itself once the collected dataset is large enough to dilute away the skew','Human bias — prejudiced choices about what to collect and label; dataset bias — unrepresentative, skewed data models learn from','Human bias — a flaw living in the algorithm’s arithmetic; dataset bias — a flaw living in the users themselves'],answer:3,
  explain:'Human bias enters through people’s decisions — which data is gathered, which labels are applied. Dataset bias is a property of the data itself — unrepresentative samples, skewed distributions, historical patterns. Both feed the model; neither is fixed by adding more of the same data.'},
 {id:'au16',yr:12,mod:'au',dots:['au-07'],type:'mcq',xp:30,
  prompt:'A hiring model is trained on ten years of a company’s biased hiring decisions. The most likely outcome is:',
  options:['The model reproduces or amplifies the bias — at scale, laundered as objective output','The model actively corrects the historical bias during its training process, unlearning the injustice','The bias disappears by itself once the training dataset is large enough overall','The model detects the biased records and refuses to train on them','Dataset bias only ever affects image recognition models, never tabular hiring datasets'],answer:0,
  explain:'A model learns the patterns in its training data — including the unjust ones — and reproduces them at scale, with the added authority of seeming mathematical. Dataset bias must be audited as rigorously as functionality; nothing in the training loop corrects it.'},
 {id:'au17',yr:12,mod:'au',dots:['au-07'],type:'mcq',xp:30,
  prompt:'The syllabus-appropriate response to discovered dataset bias is:',
  options:['Delete the biased model outright and recruit additional staff to hand-check every single decision instead','Hide the protected attributes from the model and simply hope the historical bias quietly vanishes away completely','Increase the learning rate and retrain repeatedly until the bias washes out of the trained weights','Audit the data and features, rebalance or re-collect representative data, then re-test outcomes across groups','Do nothing at all — models are neutral and unbiased by their own mathematical construction alone'],answer:3,
  explain:'Bias is treated as a defect with a lifecycle: audit the sources, rebalance or re-collect representative data, and re-test outcomes across the affected groups. Hiding protected attributes fails — proxies survive — and no hyperparameter washes bias out of unrepresentative data.'},
 {id:'au18',yr:12,mod:'au',dots:['au-02','au-03'],type:'mcq',xp:30,
  prompt:'A warehouse robot improves its pick policy through reward signals while a billing system groups unlabelled invoices. Which training models are at work — and which model family could EXPLAIN each resulting group with readable threshold rules?',
  options:['Supervised; unsupervised; a neural network could explain each cluster through its internal weights','Reinforcement; supervised; logistic regression could explain each cluster with class probabilities','Reinforcement; unsupervised; a decision tree could describe each cluster with readable threshold rules','Semi-supervised; reinforcement; KNN could explain each cluster through its nearest labelled neighbours','Unsupervised; reinforcement; linear regression could explain each cluster with a fitted line'],answer:2,
  explain:'Reward-and-penalty through interaction is reinforcement learning; finding structure in unlabelled data is unsupervised learning. For explainability, a decision tree fits: its threshold rules can be read and challenged line by line — exactly why trees were chosen over neural networks for auditable decisions.'},
/* ---- Year 12 · Software Engineering Project ---- */
 {id:'pr1',yr:12,mod:'pr',dots:['pr-01'],type:'mcq',xp:30,
  prompt:'Before committing to a project, the team judges whether the deadline and the budget can actually deliver the scope. This analysis is:',
  options:['Quality assurance — checking the product against criteria later','Scheduling and financial feasibility — part of defining requirements','Direct implementation — starting to build the full system immediately','Path coverage testing — a code-level test design measure','Version control setup — configuring the team’s shared repository'],answer:1,
  explain:'Requirements analysis judges feasibility — can the schedule and the budget deliver the scope? — before generating functionality and performance requirements and defining boundaries. QA checks quality criteria later; feasibility decides whether to begin at all.'},
 {id:'pr2',yr:12,mod:'pr',dots:['pr-01'],type:'mcq',xp:30,
  prompt:'"The report must render within 2 seconds" and "the system must not process orders outside NSW" are respectively:',
  options:['A performance requirement; a boundary definition','A functionality requirement; a performance requirement','A boundary definition; a functionality requirement','Both performance requirements','Both functionality requirements'],answer:0,
  explain:'Performance requirements say HOW WELL — response time, capacity, uptime. Boundaries say what is IN and what is OUT of the system’s scope. Functionality requirements, by contrast, say WHAT the system must do. Sorting requirement statements into their types is the assessed skill.'},
 {id:'pr3',yr:12,mod:'pr',dots:['pr-02'],type:'mcq',xp:30,
  prompt:'Match each tool to its purpose:',
  options:['Storyboard — captures data types; mind map — schedules work; data dictionary — sketches the user journey','Storyboard — the timeline; mind map — the layout only; data dictionary — the budget','Storyboard — screens in sequence; mind map — radiating ideas; data dictionary — items, types, relations','Storyboard — schedules every task; mind map — schedules every task; data dictionary — schedules every task','Storyboard — records data types; mind map — records data types; data dictionary — records data types'],answer:2,
  explain:'Tools for generating the solution each answer a different question: storyboards walk the user’s journey screen by screen, mind maps radiate ideas from a centre, and the data dictionary records items, types and relationships before coding begins. Choosing the tool that answers the question asked is the skill.'},
 {id:'pr4',yr:12,mod:'pr',dots:['pr-03'],type:'mcq',xp:30,
  prompt:'Which implementation method runs the old and new systems TOGETHER — safest, and the costliest because everything is done twice?',
  options:['Parallel — old and new systems running side by side','Direct — one immediate cutover with no fallback kept','Phased — one module at a time, across several releases','Pilot — one user group first, then the wider release','None of these — no method at all matches it'],answer:0,
  explain:'Parallel runs both systems side by side: the old system remains the fallback (safest) while every task is performed twice (costliest). Direct is a single cutover, phased rolls out module by module, and pilot trials the new system with one group before wider release.'},
 {id:'pr5',yr:12,mod:'pr',dots:['pr-03'],type:'mcq',xp:30,
  prompt:'A hospital payroll cutover cannot risk a single failed day; a two-person startup would rather switch immediately and fix issues live. The matched methods are:',
  options:['Direct for the hospital; parallel for the startup','Parallel for the hospital; direct for the startup','Phased for both','Pilot for the hospital; phased for the startup','Parallel for both'],answer:1,
  explain:'Risk appetite picks the method: where failure is unaffordable, parallel keeps the old system as a live fallback; where the cost of running two systems outweighs the risk, direct cuts over once and fixes forward. The method is chosen from consequences, not preference.'},
 {id:'pr6',yr:12,mod:'pr',dots:['pr-04'],type:'mcq',xp:30,
  prompt:'Waterfall’s defining strength and defining weakness are:',
  options:['Strength — welcomes change at any stage; weakness — poor documentation throughout','Strength — cheapest method for unstable scope; weakness — too many meetings and reviews','Strength — predictable, documented stages; weakness — late changes force costly rework','Strength — no planning required up front; weakness — heavy testing at the end','It has neither — Waterfall is a neutral default with no defining profile'],answer:2,
  explain:'Waterfall completes each stage once with thorough documentation — predictable and auditable, exactly what stable, well-specified projects need. The same property makes change expensive: a revision to signed-off requirements ripples back through design and build. The strength and the weakness are the same fact viewed from two sides.'},
 {id:'pr7',yr:12,mod:'pr',dots:['pr-05'],type:'mcq',xp:30,
  prompt:'WAgile is precisely:',
  options:['A hybrid — Waterfall planning up front plus Agile iteration','Pure Waterfall — the very same model with a new name','A database technique — migrating records between data stores','A testing methodology — rules for structuring the test effort','Agile with all planning removed — iteration with no up-front design'],answer:0,
  explain:'WAgile applies each model where it pays: up-front planning where stability helps (requirements, architecture), iteration where change helps (build and delivery). Knowing when and how each phase intervenes is the point — it is neither pure Waterfall nor planning-free Agile.'},
 {id:'pr8',yr:12,mod:'pr',dots:['pr-06'],type:'mcq',xp:30,
  prompt:'A Gantt chart primarily displays:',
  options:['Task dependencies as a network of arrows','Class relationships between objects in the system','Data flows between processes and data stores','Test coverage percentages across the whole suite','Tasks as horizontal bars against a timeline'],answer:4,
  explain:'Gantt charts schedule and track: each task is a bar positioned over the calendar, so duration, overlap and progress are visible at a glance. Dependency networks, class diagrams and data flow diagrams answer different questions entirely.'},
 {id:'pr9',yr:12,mod:'pr',dots:['pr-07'],type:'mcq',xp:30,
  prompt:'The BEST way to keep the client relationship healthy during development is to:',
  options:['Reveal the finished product only at final handover','Avoid all negotiation to protect the delivery schedule','Show working increments early, and negotiate trade-offs openly','Let developers silently infer the user’s needs without ever asking','Escalate every open question straight to the signed contract'],answer:2,
  explain:'Project communication is a running activity: involving and empowering the client, showing working increments early, and negotiating trade-offs as they arise. Surprises discovered at handover are project communication failed — and the contract is the floor of the relationship, not its channel.'},
 {id:'pr10',yr:12,mod:'pr',dots:['pr-08'],type:'mcq',xp:30,
  prompt:'Quality assurance in a software project is best described as:',
  options:['Defining quality criteria and continually checking that requirements are met','One exhaustive testing blitz on the night before the scheduled release','The client’s responsibility alone once the product has been finally handed over','An optional extra stage that only large teams need to bother with','Exactly the same single activity as running the system tests'],answer:0,
  explain:'QA is a process, not an event: quality criteria are defined up front, checked continually against the requirements, and extended to compliance and legislative obligations. A single late test blitz is inspection, not assurance — and testing is one input to QA, never the whole of it.'},
 {id:'pr11',yr:12,mod:'pr',dots:['pr-09'],type:'mcq',xp:30,
  prompt:'Two developers edit the same line of a file on different branches. At merge time the version control system reports:',
  options:['A syntax error — raised by the compiler, not the merge','A merge conflict — resolved by human intent and committed','A detached HEAD — triggered by checking out an old commit','An automatic force push — the last edit silently wins','A backup failure — the repository lost one of the branches'],answer:1,
  explain:'The system cannot decide which change was intended, so it flags a merge conflict and stops. A human resolves it by intent; the resolution is committed as the record. Version control also supplies the safety net — history, branching and rollback — that collaborative development runs on.'},
 {id:'pr12',yr:12,mod:'pr',dots:['pr-09'],type:'mcq',xp:30,
  prompt:'When implementation stalls, the syllabus orders the strategies from cheapest to most expensive:',
  options:['Search for an existing solution → collaborate with peers → outsource','Outsource the work first → search online → collaborate with peers','Collaborate with peers → outsource the work → search online','Restart from scratch → search for a quick fix → outsource','There is no documented cheapest-to-most-expensive order in the syllabus'],answer:0,
  explain:'The documented order is cost-ascending: search online for an existing solution first, collaborate with peers second, and outsource — paying someone else — last. Knowing the order is knowing the economics of getting unstuck.'},
 {id:'pr13',yr:12,mod:'pr',dots:['pr-10'],type:'mcq',xp:30,
  prompt:'A test plan for a mark validator (integers 0–100) contains the set: −1, 0, 100, 101, "abc", "". Which pair of techniques does it exercise?',
  options:['Path testing only','Boundary only — strings are not test data','Boundary testing (−1, 0, 100, 101) and abnormal data ("abc", "")','Faulty data only — numbers near the limits are not boundary data','Neither — the set is arbitrary'],answer:2,
  explain:'Boundary data sits at and just outside each limit (−1, 0, 100, 101); faulty and abnormal data breaks the type contract ("abc") or supplies no value at all (""). Together they prove the validator rejects out-of-range AND malformed input — the pair of techniques the syllabus names for generating test data.'},
 {id:'pr14',yr:12,mod:'pr',dots:['pr-10'],type:'output',xp:50,lang:'py',
  prompt:'This evaluation harness compares a run’s actual output with the expected output. What is printed?',
  code:'expected = [10, 20, 30, 40]\nactual = [10, 21, 30, 39]\npassed = 0\nfor i in range(len(expected)):\n    if actual[i] == expected[i]:\n        passed = passed + 1\nprint(passed, len(expected) - passed)',
  options:['4 0','0 4','1 3','3 1','2 2'],answer:4,
  explain:'Comparing actual with expected, element by element: 10 = 10 passes; 21 ≠ 20 fails; 30 = 30 passes; 39 ≠ 40 fails. Two passed, two failed — printed as "2 2". Evaluation IS this loop: run, compare actual with expected, feed the differences into the next iteration.'}
];

/* ---------------- QUESTS (Year 12 only) ---------------- */
var QUESTS=[
 {id:'q1',idx:0,title:'SIGNAL LOST',tag:'RELAY-3 IS THROWING INDEXERROR ON EVERY CHECKSUM',xp:120,unlock:'amber',kind:'fix',
  brief:'Something moved into the school network overnight. The staff call it BLACKGLASS — a process that lives inside the glass, refracting packets through itself. Node RELAY-3 has thrown IndexError on every checksum since 03:14, and the routing mesh is bleeding corrupted frames. Open the routine, read it the way BLACKGLASS would, and patch it.',
  fixQ:{id:'q1f',yr:12,mod:'pr',dots:['pr-10','pf-12'],type:'fix',xp:0,lang:'py',
   prompt:'RELAY-3 checksum routine — every payload raises IndexError. Find the fault and patch it. Expected: checksum("ICE") = 209, checksum("A") = 65, checksum("AB") = 131, checksum("") = 0.',
   starter:'# RELAY-3 :: packet checksum routine\n# Symptom: IndexError on every payload\ndef checksum(payload):\n    total = 0\n    i = 0\n    while i <= len(payload):\n        total = total + ord(payload[i])\n        i = i + 1\n    return total % 256',
   tests:[{label:'checksum("ICE") → 209',expr:'checksum("ICE")',expect:209},
    {label:'checksum("A") → 65',expr:'checksum("A")',expect:65},
    {label:'checksum("AB") → 131',expr:'checksum("AB")',expect:131},
    {label:'checksum("") → 0',expr:'checksum("")',expect:0}],
   explain:'The loop condition used i <= len(payload) — on the final pass the index runs past the last character and ord(payload[i]) raises IndexError, poisoning every payload. The fix is i < len(payload): an off-by-one at the boundary, exactly the class of bug that boundary test data (including the empty string) exists to catch.'}},
 {id:'q2',idx:1,title:'GHOST PROTOCOL',tag:'AN INTRUDER LEFT TRACES IN THE EDGE LOGS',xp:100,unlock:null,kind:'multi',
  brief:'BLACKGLASS rattled the edge gateway at 02:14 and left its fingerprints all over the request log. Before anyone can respond, the network team needs to know exactly what it was trying to do. Read the log. Identify the vector. Recommend the fix.',
  qs:[
   {id:'q2a',yr:12,mod:'ss',dots:['ss-06','ss-02'],type:'log',xp:0,
    prompt:'The SOC pulls this from the edge gateway. What attack is in progress?',
    log:'02:14:07 HTTP GET /products?id=1’ OR ’1’=’1 --          200\n02:14:09 HTTP GET /products?id=1’ UNION SELECT user,pass FROM users--  500\n02:14:11 HTTP GET /products?id=1’; DROP TABLE sessions--  500\n02:14:13 HTTP GET /admin                               403',
    options:['SQL injection probing the products endpoint','A distributed denial-of-service','Cross-site scripting stored in product pages','Credential brute-force'],answer:0,
    explain:'Quote characters, an OR tautology, UNION extraction and a DROP payload — the textbook sequence of SQL injection reconnaissance.'},
   {id:'q2b',yr:12,mod:'ss',dots:['ss-06'],type:'mcq',xp:0,
    prompt:'The fastest durable fix at the code level:',
    options:['Parameterise the query and reject non-integer id values at the boundary','Permanently block the attacker’s IP address','Rename /products to /p so attackers can’t find it','Buy a bigger firewall appliance'],answer:0,
    explain:'Parameterisation kills the vulnerability class forever. IP blocking and obscurity only dodge today’s attacker.'},
   {id:'q2c',yr:12,mod:'ss',dots:['ss-06','ss-08'],type:'mcq',xp:0,
    prompt:'From the log alone: the OR 1=1 probe returned 200 while the UNION probe returned 500. What did the 200 most likely indicate?',
    options:['The tautology made the WHERE clause always true, so the query succeeded and data may have leaked','The server was healthy — a 200 always means the request was safe','The firewall silently blocked the probe','The UNION failing proves no query executed at all'],answer:0,
    explain:'A 200 on the tautology probe means the altered query executed and returned rows — the classic silent data-exposure signature. Status codes must be read together with the payload; 500s on the follow-ups show the later probes broke the query, not that nothing happened.'}]},
 {id:'q3',idx:2,title:'ICE WALL',tag:'THE AUTH VAULT STILL HASHES LIKE IT’S 2009',xp:130,unlock:'magenta',kind:'multi',
  brief:'The auth vault predates everyone in this building. Unsalted digests, a password gate that accepts anything. BLACKGLASS feeds on credentials like these. Clear the audit, then finish the policy gate the night shift never completed.',
  qs:[
   {id:'q3a',yr:12,mod:'ss',dots:['ss-02'],type:'mcq',xp:0,
    prompt:'Two users both choose the password "hunter2". Without salting, their stored hashes are identical. What is the main risk?',
    options:['Cracking one account instantly exposes every account sharing that password','The hash becomes reversible','The database stores duplicate rows','The hash algorithm slows down'],answer:0,
    explain:'Identical digests enable rainbow-table and cross-user attacks: one crack unlocks all accounts with the same password. Salts make every digest unique.'},
   {id:'q3b',yr:12,mod:'ss',dots:['ss-03'],type:'mcq',xp:0,
    prompt:'Which is the appropriate way to store login passwords today?',
    options:['A slow, salted hash such as bcrypt or Argon2','MD5 of the password','A plain SHA-256 of the password','AES-encrypted with a server key'],answer:0,
    explain:'Password storage wants slow and salted — bcrypt / Argon2 — so brute force is expensive. Fast hashes and reversible encryption are both wrong tools.'},
   {id:'q3c',yr:12,mod:'ss',dots:['ss-05'],type:'mcq',xp:0,
    prompt:'A DAST report flags information disclosure: /error returns a full stack trace to users. Best remediation?',
    options:['Log the detail server-side and show a generic message with a correlation ID','Remove the error page so failures are invisible','Disable exceptions in the language','Show stack traces only to logged-in admins'],answer:0,
    explain:'Server-side logs keep the detail for engineers; users get a generic message. The correlation ID stitches the two together across an incident — failing securely.'},
   {id:'q3d',yr:12,mod:'ss',dots:['ss-02','ss-06'],type:'fix',xp:0,lang:'py',
    prompt:'Finish the password policy gate. A password is STRONG only if it is at least 10 characters AND contains at least one letter, one digit and one symbol (non-alphanumeric).',
    starter:'# AUTH VAULT :: password policy gate (incomplete)\n# STRONG: length >= 10 AND at least one letter,\n# one digit and one symbol (non-alphanumeric)\ndef is_strong(pw):\n    return True',
    tests:[{label:'is_strong("correcthorse") → False',expr:'is_strong("correcthorse")',expect:false},
     {label:'is_strong("battery9staple$") → True',expr:'is_strong("battery9staple$")',expect:true},
     {label:'is_strong("12345678901") → False',expr:'is_strong("12345678901")',expect:false},
     {label:'is_strong("short1!") → False',expr:'is_strong("short1!")',expect:false},
     {label:'is_strong("aaaaaaaaa1") → False',expr:'is_strong("aaaaaaaaa1")',expect:false},
     {label:'is_strong("Battery9!") → False',expr:'is_strong("Battery9!")',expect:false},
     {label:'is_strong("staple&&&&9x") → True',expr:'is_strong("staple&&&&9x")',expect:true}],
    explain:'Four checks, fail-closed: length at least 10, then a single pass classifying every character — a letter (a–z / A–Z), a digit (0–9), or a symbol (everything else) — and require all three flags True. Boundary cases do the damage: 9 characters fails, digits-only fails, no-symbol fails.'}]},
 {id:'q4',idx:3,title:'ARCHITECT’S EYE',tag:'A SINGLE POINT OF FAILURE HIDES IN THE BLUEPRINT',xp:110,unlock:'ice',kind:'multi',
  brief:'Blueprints for SUBNET OBSIDIAN just landed on your desk — the topology the school brings online at dawn. BLACKGLASS has already read them. Somewhere in that diagram hides a single point of failure that would take the whole subnet dark. Find it before it is built, not after.',
  qs:[{id:'q4a',yr:12,mod:'ss',dots:['ss-02','ss-05'],type:'diagram',xp:0,diag:'arch1',
   prompt:'SUBNET "OBSIDIAN" goes online at dawn. Click the component that is a single point of failure for the whole subnet.',
   explain:'Both edge routers, the WAF and the caches are redundant pairs, and the queue is mirrored. The primary database stands alone — no replica, no failover — and every service depends on it. Availability, one of the core security concepts, and business continuity are exactly what the missing replica sacrifices.'}]},
 {id:'q5',idx:4,title:'FINAL BREACH',tag:'BLACKGLASS HAS STOPPED HIDING',xp:200,unlock:null,kind:'gauntlet',
  brief:'BLACKGLASS has stopped hiding. It is moving through the network’s own systems — injection probes, forged credentials, poisoned logs, poisoned models. This is the gauntlet: five randomised encounters drawn from every Year 12 focus area — Secure Software Architecture, Programming for the Web, Software Automation and the Project. Clear them all and the network holds. Stumble, and it does not.'}];
function questUnlocked(q){ return q.idx===0 || !!state.quests[QUESTS[q.idx-1].id]; }
var COOP_Q={id:'coop',yr:12,mod:'ss',dots:['ss-06'],type:'fix',xp:100,lang:'py',
 prompt:'NULLPTR_NINA started hardening the intake port validator and clocked off mid-shift. Finish her patch: accept integers in range 0–65535, or digit-only strings that parse to a port in that range. Reject everything else — including booleans, because in Python True is an int.',
 starter:'# CO-OP RELAY :: intake port validator\n# TODO(nina): reject out-of-range values (0-65535)\n# TODO(you): reject non-integers and non-digit strings\n# HINT: in Python, True is an int -- filter bools first!\ndef validate_port(value):\n    return True',
 tests:[{label:'validate_port(8080) → True',expr:'validate_port(8080)',expect:true},
  {label:'validate_port("443") → True',expr:'validate_port("443")',expect:true},
  {label:'validate_port(0) → True',expr:'validate_port(0)',expect:true},
  {label:'validate_port(65535) → True',expr:'validate_port(65535)',expect:true},
  {label:'validate_port(99999) → False',expr:'validate_port(99999)',expect:false},
  {label:'validate_port("80a") → False',expr:'validate_port("80a")',expect:false},
  {label:'validate_port(-1) → False',expr:'validate_port(-1)',expect:false},
  {label:'validate_port(3.5) → False',expr:'validate_port(3.5)',expect:false},
  {label:'validate_port("") → False',expr:'validate_port("")',expect:false},
  {label:'validate_port(True) → False',expr:'validate_port(True)',expect:false},
  {label:'validate_port(None) → False',expr:'validate_port(None)',expect:false}],
 explain:'Validate at the boundary: filter bools FIRST (True is an int in Python), then allow-list integers to 0–65535, then digit-only strings parsed with int() and range-checked again. Everything else fails closed, not open.'};
